  if (n.cat === 'motor') return `<circle cx="${x}" cy="${y}" r="13" fill="${css('--sheet')}" stroke="${col}" stroke-width="1.6"/><text x="${x}" y="${y + 4}" text-anchor="middle" font-size="12" font-weight="600" fill="${col}">M</text>`;
