    s += `<rect class="busbar" x="${x0}" y="${y - 4}" width="${x1 - x0}" height="8" fill="${ink}" stroke="transparent" stroke-width="6"/>`;
    s += `<rect x="${x0}" y="${y - 22}" width="${x1 - x0}" height="40" fill="transparent"/>`;
