    const pdf = new window.jspdf.jsPDF({ orientation: 'landscape', unit: 'mm', format: [mw, mh], compress: true }); let first = true, n = 0;
    for (const e of entries) {
      SHEET = e.s; if (e.board) KNXSCH = e.board; PG = 0; renderSheet(); const pages = SEGN;
      for (let i = 0; i < pages; i++) {
        PG = i; if (i) renderSheet(); if (btn) btn.textContent = `Making the PDF… ${++n}`;
        const cv = await window.html2canvas($('#a3'), { scale: sc, backgroundColor: '#ffffff', logging: false, width: 1190, height: 842, onclone: (d) => { const a = d.getElementById('a3'); a.style.border = '0'; a.style.margin = '0'; } });
