  if (r.rcdIn) mods.push({ t: 'RCCB', m: 4, label: 'RCCB S 300mA', sub: 'TT', col: '--rcd' });
  if (r.spd) mods.push({ t: 'SPD', m: r.spd === 'T2' ? 4 : 8, label: `SPD ${r.spd}`, sub: '4P', col: '--spd' });
