  { const ps = ways.filter(({ r: w }) => w.prog); if (ps.length) { if (ps.some(({ r: w }) => /photo/.test(w.ctrl))) mods.push({ t: 'TIM', m: 1, label: 'PEC', sub: 'photo', col: '--cont' }); const np = new Set(ps.map(({ r: w }) => w.ctrl + w.prog.on + w.prog.off)).size; for (let i = 0; i < Math.ceil(np / 2); i++) mods.push({ t: 'TIM', m: 2, label: 'Astro', sub: 'timer', col: '--cont' }); } }
  { const K = knxPlan(); const kb = knxBoard(K, bd.id); if (kb) { if (K.boards[0]?.board.id === bd.id && KNX.coupling === 'tp') mods.push({ t: 'KNX', m: 4, label: 'PSU 320', sub: knxArt('psu320'), col: '--meter' }, { t: 'KNX', m: 2, label: 'IP intf', sub: 'IPS 300', col: '--meter' }); K.lines.filter((L) => L.bids[0] === bd.id).forEach((L1) => mods.push({ t: 'KNX', m: 4, label: `PSU ${L1.psu}`, sub: knxArt('psu' + L1.psu), col: '--meter' }, { t: 'KNX', m: 2, label: KNX.coupling === 'tp' ? 'Line cpl' : 'IP rtr', sub: KNX.coupling === 'tp' ? '21420 1S R' : 'IPR 300', col: '--meter' })); Object.entries(kb.dev).forEach(([k, n]) => { if (!KNX_DEV[k]?.mod) return; for (let i = 0; i < n; i++) mods.push({ t: 'KNX', m: KNX_DEV[k].mod, label: { sa16: 'SA 16×', sa8: 'SA 8×', sa4: 'SA 4×', dim4: 'Dim 4×', ctl110: '1–10 V 4×', dali: 'DALI', bin: 'BI 6×', bl4: 'Blind 4×', bl8: 'Blind 8×', gwBac: 'BACnet', gwCbus: 'C-Bus', gwDmx: 'DMX', gwAc: 'AC gw' }[k] ?? k, sub: KNX_DEV[k].art.split(' ')[0], col: '--meter' }); }); } }
  const used = mods.reduce((t, d) => t + d.m, 0);
