  const screw = (cx, cy, r) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="#C9CDCF" stroke="#7D868A" stroke-width="0.6"/><path d="M${cx - r * 0.7} ${cy}h${r * 1.4}" stroke="#5B6469" stroke-width="0.8"/>`;
