      for (let i = 0; i < Math.min(8, n * 2); i++) s += `<circle cx="${x + 5 + (i % 4) * ((w - 10) / 3.4)}" cy="${fy + fh * (0.4 + Math.floor(i / 4) * 0.13)}" r="1.8" fill="${i % 3 ? '#2E9B48' : '#9AA3A7'}"/>`;
