  for (let i = 0; i < Math.min(c.n, 8); i++) { const x = fx0 + ((i + 0.5) * (fx1 - fx0)) / Math.min(c.n, 8); s += `<rect x="${x - 5}" y="${top - 2}" width="10" height="12" fill="#F2B705" stroke="${ink}" transform="rotate(${c.tilt} ${x} ${top})"/>`; }
