  s += `<rect x="${cx - hd.bp * k * 0.8}" y="${gy - 4}" width="${hd.bp * k * 1.6}" height="${pd * 0.7}" fill="#D9D4C8" stroke="${ink}"/><rect x="${cx - B / 2}" y="${gy + pd * 0.7}" width="${B}" height="${pd * 0.3 + 4}" fill="#D9D4C8" stroke="${ink}"/>`;
