  s += `<path d="M${cx - 6} ${gy - 6}C${cx - 30} ${gy + 4} ${cx - B / 2 - 10} ${gy + 4} ${cx - B / 2 - 14} ${gy + 10}M${cx + 6} ${gy - 6}C${cx + 30} ${gy + 4} ${cx + B / 2 + 10} ${gy + 4} ${cx + B / 2 + 14} ${gy + 10}" fill="none" stroke="${gr}" stroke-width="1.6"/>`;
