    const t = [...l.childNodes].find((n) => n.nodeType === 3 && n.textContent.trim()), sp = document.createElement('span'); sp.className = 'flab';
    if (t) sp.appendChild(t); sp.appendChild(b); l.insertBefore(sp, l.firstChild);
