  E.forEach((e) => { SHEET = e.s; if (e.board) KNXSCH = e.board; PG = 0; renderSheet(); e.pages = SEGN; });
  KNXPACK = E; SHEET = keep.SHEET; PG = keep.PG; KNXSCH = keep.KNXSCH;
