}
function knxSysHtml() {
  const K = KNX.on ? knxPlan() : null, T = K?.total ?? {}, keys = ['psu160', 'psu320', 'psu640', 'psu1280', 'ipr', 'lc', 'ips', 'lgc', 'spd'].filter((k) => T[k]);
  const chip = (k, n) => `<div class="pal kpal kdev" style="cursor:default" title="${esc(KNX_DEV[k].name)}"><b>${KSHORT[k]}${n ? ` × ${n}` : ''}</b><small>${esc(KNX_DEV[k].art)}</small></div>`;
  const shown = keys.length ? keys.map((k) => chip(k, T[k])).join('') : [KNX.psu === 'auto' ? null : 'psu' + KNX.psu, KNX.coupling === 'tp' ? 'lc' : 'ipr'].filter((k) => k && KNX_DEV[k]).map((k) => chip(k)).join('');
  return `<section class="ksec kwide"><h3>System devices – one set per line</h3><div class="kgrid">${shown}</div>
    <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:end;margin-top:6px">${selectF('Line supply', 'kp_psu', KNX.psu, [['auto', 'Auto – smallest that fits each line'], [160, '160 mA – 20160 REG'], [320, '320 mA – 20320 REG'], [640, '640 mA – 20640 REG'], [1280, '1280 mA – 21280 REG']])}${selectF('Line coupling', 'kp_cpl', KNX.coupling, [['ip', 'IP router per line – IPR 300 SREG'], ['tp', 'Line coupler per line – 21420 1S R']])}</div>
    <p class="note">Each line gets its own supply and coupler, sized from its bus current${K && !K.empty ? ` – now ${K.lines.length} line${K.lines.length === 1 ? '' : 's'}${(K.areas ?? []).length > 1 ? ` in ${K.areas.length} areas` : ''}` : ''}. Areas and named lines: Controls &amp; KNX → Areas &amp; lines.</p></section>`;
}
function renderKnxPalette() {
  const el = $('#kpalette'), elig = knxEligible();
  if (kclear && Date.now() - kclear > 5000) kclear = 0;
  const item = (k) => `<div class="pal kpal kdev${karmed?.key === k ? ' armed' : ''}" data-kadd="${k}" title="${esc(KNX_DEV[k].name)}"><b>${KSHORT[k]}</b><small>${esc(KNX_DEV[k].art.startsWith('Third party') ? 'Third party' : KNX_DEV[k].art)}</small></div>`;
  const help = (txt, lab = 'ⓘ') => `<details class="khelp"><summary>${lab}</summary><p class="note">${txt}</p></details>`; // help folded away: the palette shows devices, not paragraphs
  const sec = (title, keys, note = '') => `<section class="ksec"><div class="khead"><h3>${title}</h3>${note ? help(note) : ''}</div><div class="kgrid">${keys.map(item).join('')}</div></section>`;
  el.innerHTML = `<div class="ksecs">
    <section class="ksec kwide"><div class="khead"><h3>Power circuits</h3><div class="kbar"><button class="btn" id="k_all">All indoor lighting on KNX</button><button class="btn" id="k_none" style="${kclear ? 'border-color:var(--bad);color:var(--bad)' : ''}">${kclear ? 'Tap again to clear' : 'Clear'}</button></div>${help('Any circuit can go on KNX – lighting, sockets, AC, pumps, blinds. Drag it onto a board (an output is picked for it), straight onto an actuator output (A1, A2 …), or onto a push-button / sensor. On a tablet: tap the circuit, then tap the board, output or device. Tap an output to choose its circuit. Loads above 16 A, 3-phase or motors are switched through a contactor (+K on the output). Emergency lighting stays off KNX (BS 5266).', 'How to place')}</div>
      <div class="kgrid kcirc">${elig.map(({ k, b }) => { const on = lastCalc.out.get(k.id)?.ctrl === 'knx', off = knxRole(k).kind === 'off'; return `<div class="pal kpal${karmed?.load === k.id ? ' armed' : ''}${on ? ' on' : ''}${off ? ' koff' : ''}" data-kload="${k.id}" title="${off ? esc(knxRole(k).why) : ''}"><span class="kdot">${on ? '●' : off ? '⊘' : '○'}</span><span class="kname">${esc(k.name)}</span><small>${{ light: 'Light', flood: 'Flood', street: 'Street', socket: 'Socket', motor: 'Motor', hvac: 'AC' }[k.cat] ?? ''} · ${esc(b.name)}</small></div>`; }).join('') || '<p class="note">No circuits yet – add them on the power side.</p>'}</div></section>
    ${sec('Actuators (Jung)', KACT)}
    ${sec('Field devices', KFIELD, 'Push-buttons: choose 2, 3, 4, 6 or 8 gangs and a display after placing.')}
    ${sec('Gateways', KGW)}
    ${sec('Central control (IP)', KIP)}
    ${knxSysHtml()}
  </div>`;
  el.querySelector('#kp_psu')?.addEventListener('change', (e) => { KNX.psu = e.target.value === 'auto' ? 'auto' : +e.target.value; update(false); });
  el.querySelector('#kp_cpl')?.addEventListener('change', (e) => { KNX.coupling = e.target.value; update(false); });
}
function renderKnxInsp() {
