// ---- results against the targets
function lcResHtml(L, R) {
  const tg = L.tg, std = LC_STD[L.std] ?? LC_STD.custom, ok = (v, t, f = 0) => !t || v + 1e-9 >= t * (1 - f), cell = (v, t, d = 0, unit = '') => `<td class="m" style="color:${!t ? 'inherit' : ok(v, t) ? 'var(--ok)' : 'var(--bad)'};font-weight:600">${t ? (ok(v, t) ? '✓ ' : '✕ ') : ''}${d ? v.toFixed(d) : Math.round(v)}${unit}</td>`;
  let pass = 0, fail = 0; const cnt = (b) => (b ? pass++ : fail++);
  const none = `<td class="m note">no points</td>`, rowsEh = LC_AREAS.map(([a, n]) => { const S = lcStats(R, R.Eh, a), t = tg[a] ?? {}; if (!S.n) return `<tr><td><b>${n}</b></td><td class="m note" colspan="4">not on the drawing – mark it to calculate here</td><td class="m">${t.Eh ?? '–'} lx · ${t.U1 ?? '–'} · ${t.U2 ?? '–'}</td></tr>`; cnt(ok(S.av, t.Eh)); cnt(ok(S.U1, t.U1)); cnt(ok(S.U2, t.U2)); return `<tr><td><b>${n}</b></td>${cell(S.av, t.Eh, 0, ' lx')}<td class="m">${Math.round(S.mn)} / ${Math.round(S.mx)}</td>${cell(S.U1, t.U1, 2)}${cell(S.U2, t.U2, 2)}<td class="m">${t.Eh ?? '–'} lx · ${t.U1 ?? '–'} · ${t.U2 ?? '–'}</td></tr>`; }).join('');
  const rowsC = R.cams.map((c, ci) => `<tr><td><b>C${L.cams.indexOf(c) + 1}</b> ${esc(c.n)}</td>${LC_AREAS.map(([a]) => { const S = lcStats(R, R.Ec[ci], a), t = tg[a] ?? {}; if (!S.n || !lcCamAp(L, c, a)) return none; const gE = ok(S.av, t.Ec), g1 = ok(S.U1, t.U1), g2 = ok(S.U2, t.U2), g = gE && g1 && g2, col = (b) => (b ? 'var(--ok)' : 'var(--bad)'); cnt(g); return `<td class="m"><span style="color:${col(g)}">${g ? '✓' : '✕'}</span> <span style="color:${col(gE)}">${Math.round(S.av)} lx</span><br><small><span style="color:${col(g1)}">U1 ${S.U1.toFixed(2)}${t.U1 ? ` (${t.U1})` : ''}</span> · <span style="color:${col(g2)}">U2 ${S.U2.toFixed(2)}${t.U2 ? ` (${t.U2})` : ''}</span></small></td>`; }).join('')}</tr>`).join('');
