  return `<div class="row" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:8px"><b>View</b><select id="lc_view">${[['Eh', 'Horizontal Eh'], ['surf', 'Surfaces – materials & colours'], ['min', 'Ecam – lowest of all cameras'], ...R.cams.map((c, i) => ['c' + i, `Ecam → C${L.cams.indexOf(c) + 1} ${c.n}`])].map(([v, t]) => `<option value="${v}"${L.view === v ? ' selected' : ''}>${esc(t)}</option>`).join('')}</select><label class="f chk"><input type="checkbox" id="lc_iso" ${L.iso ? 'checked' : ''}> isolux lines</label><label class="f chk"><input type="checkbox" id="lc_best" ${L.best !== false ? 'checked' : ''}> best mast locations</label><select id="lc_aimshow">${[['sel', 'Aiming: selected mast'], ['all', 'Aiming: all masts'], ['none', 'Aiming: hidden']].map(([v, t]) => `<option value="${v}"${L.aimShow === v ? ' selected' : ''}>${t}</option>`).join('')}</select><span class="note">Tap a mast for its aiming arrows, an arrow end to aim one luminaire; drag masts, cameras and aim points.</span></div>
