  let h = `${LCFULL ? '<button class="btn lcFsx" id="lc_fsx" style="position:fixed;top:10px;right:14px;z-index:900;background:var(--ink);color:var(--bg);box-shadow:0 2px 8px rgba(0,0,0,.25)">✕ Exit full screen</button>' : ''}<div class="lcTools" style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px"><button class="btn" id="lc_fs">${LCFULL ? '✕ Exit full screen' : '⛶ Full screen'}</button><label class="btn" style="cursor:pointer">Import Relux .rdf<input type="file" id="lc_rdfin" accept=".rdf" hidden></label><button class="btn" id="lc_rdfnew" title="A new Relux project with every floodlight, its aiming and photometry, the ground and the main camera – no .rdf of your own needed">Export new .rdf</button><button class="btn" id="lc_dxf" title="The ground drawing – ground lines, calculation areas, masts, aiming lines and cameras – as a DXF plan at the same place as the exported Relux project">Export plan .dxf</button></div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:6px"><button class="btn" id="lc_undo"${LCUNDO.length ? '' : ' disabled style="opacity:.45"'}>↶ Undo${LCUNDO.length ? ` – ${esc(LCUNDO[LCUNDO.length - 1].what)}` : ''}</button><span class="note">${LCUNDO.length ? `${LCUNDO.length} step${LCUNDO.length > 1 ? 's' : ''} back` : 'nothing to undo'}</span><span style="flex:1"></span><button class="btn" id="lc_pdf">PDF report</button><button class="btn" id="lc_pdfaim">Aiming PDF</button><button class="btn" id="lc_pdfpts" title="Every point's lux on the ground layout: Eh and Ev towards each camera">Point values PDF</button><select id="lc_ptpaper" title="Paper for the point values – the whole ground on one sheet">${[['auto', 'Auto – A3, A2 or A1'], ['a1', 'A1'], ['a2', 'A2'], ['a3', 'A3 (scaled to fit)'], ['a4', 'A4 (scaled to fit)']].map(([v, n]) => `<option value="${v}"${(L.ptPaper ?? 'auto') === v ? ' selected' : ''}>${n}</option>`).join('')}</select><button class="btn" id="lc_gosend" style="background:var(--ink);color:var(--bg)">⇢ Send to electrical</button></div>`;
  h += `<div style="border:1.5px solid var(--ink);border-radius:10px;padding:8px 10px;margin-bottom:8px">${lcSportSel(L)}<button class="btn" id="lc_auto" style="background:#c8102e;color:#fff;border-color:#c8102e;width:100%;font-size:14px;padding:9px">${LCBUSY === 'auto' ? 'Designing…' : 'Complete the design automatically'}</button>${lcPosHtml(L)}<div class="grid2" style="margin-top:6px"><label class="f">Lowest mast height m<input type="number" id="lc_hlo" min="0" step="1" placeholder="no limit" value="${+L.hMin || ''}"></label><label class="f">Highest mast height m<input type="number" id="lc_hhi" min="0" step="1" placeholder="no limit" value="${+L.hMax || ''}"></label></div><p class="note" style="margin:4px 0 0">Luminaires: <b>${lcUseIds(L).map((id) => esc(L.lums[id]?.name ?? id)).join(' · ')}</b>${lcUseIds(L).length > 1 ? ' – each alone and mixed' : ''} (tick more under Luminaires). ${lcLinked() ? `Uses the ${L.masts.length} masts of the stadium layout (Cable distribution)` : 'Places the masts'}, sets the heights and floodlights, aims and optimises until the targets are met, then lowers the masts towards the lowest allowed and removes floodlights while every check still passes (about a minute per option)${lcLinked() ? ' – and sends the result to the electrical design' : ''}. ↶ Undo goes back to before it.</p>${lcAutoStatsHtml(L)}${L.autoCmp?.length > 1 ? (() => { const one = L.autoCmp.filter((r) => !r.name.startsWith('Mixed: ')), sh = lcShortNames(one.map((r) => r.name)), mp = new Map(one.map((r, k) => [r.name, sh[k]])), sn = L.autoCmp.map((r) => (r.name.startsWith('Mixed: ') ? r.name.slice(7).split(' + ').map((x) => mp.get(x) ?? x).join(' + ') : mp.get(r.name) ?? r.name)); return `<div class="tablewrap" style="margin-top:6px"><table class="sch"><thead><tr><th>Option tried</th><th>Checks</th><th>Floodlights</th><th>Masts m</th><th>kW</th><th></th></tr></thead><tbody>${L.autoCmp.map((r, i) => { const on = L.autoShown === i; return `<tr style="${on ? 'background:rgba(42,111,219,.1);' : ''}${r.best ? 'font-weight:700' : ''}"><td>${r.best ? '★ ' : ''}${r.name.startsWith('Mixed') ? `Mixed: ${esc(sn[i])}` : esc(sn[i])}${r.fails && r.why ? `<br><small style="color:var(--bad);font-weight:400">${esc(r.why)}</small>` : ''}</td><td style="color:${r.fails ? 'var(--bad)' : 'var(--ok)'}">${r.fails ? `${r.fails} to fix` : 'all pass'}</td><td class="m">${r.N}</td><td class="m">${r.H}${r.Hmin ? `<br><small style="font-weight:400">min ${r.Hmin}</small>` : ''}</td><td class="m">${r.kW}</td><td>${LCOPTS[i] ? (on ? '<span class="note">showing</span>' : `<button class="btn" data-lcopt="${i}">View</button>`) : ''}</td></tr>`; }).join('')}</tbody></table></div><p class="note" style="margin:4px 0 0">★ the best option (passes with the lowest masts and fewest floodlights). <b>View</b> puts an option on the plan, the results and the PDF – ↶ Undo goes back.${LCOPTS.length ? '' : ' (Run it again to view the other options – they are kept until the design is closed.)'}</p>`; })() : ''}</div>`;
  h += `<details open><summary><b>Automatic design</b></summary><p class="note" style="margin:4px 0">${esc(S.why)}. Suggested height: every mast ${S.H[0] ?? '–'} m${+L.hMin || +L.hMax ? ` (limits ${+L.hMin || 'none'} – ${+L.hMax || 'none'} m)` : ''}.</p>
    <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:end;margin-bottom:6px">${selectF(lcSport(L).pole === 'P' ? 'Poles' : 'Masts', 'lc_pn', lcBestN(L), [...((lcSport(L).minM ?? 6) <= 4 ? [[4, '4']] : []), [6, '6'], [8, '8'], [10, '10'], [12, '12']])}<button class="btn" id="lc_place" style="background:var(--ink);color:var(--bg)">${LCBUSY === 'place' ? 'Placing…' : 'Place the masts automatically'}</button></div><div class="grid2"><label class="f">Lowest mast height m<input type="number" id="lc_hmin" min="0" step="1" placeholder="no limit" value="${+L.hMin || ''}"></label><label class="f">Highest mast height m<input type="number" id="lc_hmax" min="0" step="1" placeholder="no limit" value="${+L.hMax || ''}"></label></div><div class="grid2"><label class="f">Minimum distance between masts m<input type="number" id="lc_gap" min="5" step="1" placeholder="auto ${lcGapAuto(L)}" value="${+L.gap || ''}"></label><span class="note" style="align-self:end">Every mast ends at the same height.</span></div><label class="f chk"><input type="checkbox" id="lc_sym" ${L.sym === false ? '' : 'checked'}> Keep the layout symmetrical (play in both directions) – untick to let the automatic design move masts one by one</label>${lcMzActive(L) ? `<p class="note" style="margin:0;color:#15803d">Masts are placed only in the ${L.mz.length} marked mast area${L.mz.length > 1 ? 's' : ''}.</p>` : ''}<div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" id="lc_sug">Apply the suggested heights & count</button><button class="btn" id="lc_aim">Aim automatically</button><button class="btn" id="lc_opt" style="background:var(--ink);color:var(--bg)">${LCBUSY === true ? 'Optimising…' : 'Optimise the aiming'}</button><button class="btn" id="lc_full">Do it all</button></div>${LCMSG ? `<p class="note" style="margin:6px 0 0">${esc(LCMSG)}</p>` : ''}
    ${FX && !LCBUSY ? `<div style="border:1.5px solid var(--sel);border-radius:10px;padding:8px 10px;margin-top:8px;background:rgba(42,111,219,.06)"><b>Suggestion to meet the targets</b><div style="margin:4px 0">${[same(L.masts.map((m) => m.lights.length)) !== '' && same(FX.N) !== '' ? `Floodlights per mast <b>${L.masts[0].lights.length} → ${FX.N[0]}</b>` : `Floodlights <b>${L.masts.reduce((t, m) => t + m.lights.length, 0)} → ${FX.N.reduce((t, v) => t + v, 0)}</b> (each mast +${Math.round((FX.f - 1) * 100)} %)`, FX.up ? (same(L.masts.map((m) => m.h)) !== '' && same(FX.H) !== '' ? `mast height <b>${L.masts[0].h} → ${FX.H[0]} m</b>` : 'every mast about 8 % higher') : ''].filter(Boolean).join(' · ')}</div><p class="note" style="margin:0 0 6px">Short: ${esc(FX.why.slice(0, 4).join('; '))}${FX.why.length > 4 ? ` and ${FX.why.length - 4} more` : ''}. New floodlights copy the existing aiming; optimise after.</p><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" id="lc_fixopt" style="background:var(--ink);color:var(--bg)">Apply and optimise</button><button class="btn" id="lc_fix">Apply only</button></div></div>` : ''}</details>`;
  h += lcScPanel(L);
  const hs = L.masts.map((m) => m.h), ns = L.masts.map((m) => m.lights.length);
  h += `<details open><summary><b>Heights & floodlights</b> <span class="note">${L.masts.length} masts · ${ns.reduce((t, v) => t + v, 0)} floodlights</span></summary>${lcRunBanner(L)}<div class="grid2">${num('Height of all masts m', 'lc_allh', same(hs), 'min="5" max="80" step="0.5" placeholder="mixed"')}${num('Floodlights on every mast', 'lc_alln', same(ns), 'min="1" max="300" step="1" placeholder="mixed"')}</div>
    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:6px"><button class="btn" data-lcadj="h:1">All masts +1 m</button><button class="btn" data-lcadj="h:-1">−1 m</button><button class="btn" data-lcadj="n:2">All masts +2 floodlights</button><button class="btn" data-lcadj="n:-2">−2</button><button class="btn" data-lcadj="n:10%">+10 %</button></div>
    <div class="tablewrap"><table class="sch"><thead><tr><th>Mast</th><th title="To the bottom of the head frame">Height m</th><th>Floodlights</th><th>Frame</th><th></th></tr></thead><tbody>${L.masts.map((m, i) => `<tr${lcRunRow(L, i)}><td><b>${lcMastIssues(L, m).length ? '⚠ ' : ''}${esc(m.name)}</b></td><td>${m.roof ? `<b>${m.h}</b> <small>roof</small>` : `<input type="number" data-lcmh="${i}" value="${m.h}" min="5" max="80" step="0.5" style="width:70px">`}${lcRunWas(L, i, 'h')}</td><td><input type="number" data-lcmn="${i}" value="${m.lights.length}" min="1" max="300" step="1" style="width:70px">${lcRunWas(L, i, 'n')}</td><td class="m"><small>${(({ t, rows, cols, W, H }) => (t === 'ring' ? `ring Ø ${W} m` : `${W} × ${H} m<br>${cols} per row × ${rows} rows${t === 'grid' ? '' : ' · ' + (LC_FRAMES[t] ?? (t === 'line' ? 'Roof catwalk' : '')).split(' – ')[0].toLowerCase()}`))(lcFrameGeom(m))}</small></td><td><button class="btn" data-lcsm="${i}">Open</button></td></tr>`).join('')}</tbody></table></div><p class="note" style="margin:0">Changing a count keeps the aiming – new floodlights copy the existing aim points. Then optimise the aiming. ↶ Undo goes back one step.</p></details>`;
  if (sel?.t === 'm' && L.masts[sel.i]) { const m = L.masts[sel.i], f = m.frame ?? {};
    const iss = lcMastIssues(L, m);
    h += `<details open id="lcSelBox"><summary><b>Mast ${esc(m.name)}</b></summary>${lcScMastSel(L, m)}${iss.map((i) => `<p class="note" style="margin:2px 0;color:var(--bad)">⚠ ${esc(i.t)}</p>`).join('')}<div class="grid2">${field('Name', 'lcm_name', m.name, 'text')}${num('Mast height m – to the bottom of the head frame', 'lcm_h', m.h, 'min="5" step="0.5"')}</div><div class="grid2">${num('x m', 'lcm_x', m.x, 'step="0.5"')}${num('y m', 'lcm_y', m.y, 'step="0.5"')}</div>
      <div class="grid2">${num('Luminaires', 'lcm_n', m.lights.length, 'min="1" max="300" step="1"')}${selectF('Luminaire type', 'lcm_lum', m.lum ?? '', [['', 'Project luminaire'], ...lumOpts])}</div>
      <div class="grid2">${selectF('Head frame', 'lcm_ft', f.t ?? 'grid', Object.entries(LC_FRAMES))}${f.t === 'ring' ? num('Ring radius m', 'lcm_fr', f.r ?? 1.5, 'min="0.5" step="0.1"') : +f.w > 0 ? `<label class="f">Luminaires per row<input disabled value="${lcFrameGeom(m).cols} (from the width)"></label>` : num('Luminaires per row (blank = auto)', 'lcm_fc', f.cols ?? '', `min="1" step="1" placeholder="${lcFrameGeom(m).cols}"`)}</div>
      ${f.t === 'ring' ? '' : `<div class="grid2">${num('Head frame tilt ° (top towards the field)', 'lcm_ftl', +f.tilt || '', 'min="0" max="30" step="1" placeholder="0"')}<span></span></div>`}
      ${f.t === 'ring' ? '' : `<div class="grid2">${num('Head frame width m (blank = luminaires per row)', 'lcm_fw', +f.w > 0 ? f.w : '', 'min="0.8" step="0.1"')}<label class="f">Head frame<input disabled value="${(({ cols, rows, W, H }) => `${cols} per row × ${rows} rows · ${W} × ${H} m`)(lcFrameGeom(m))}"></label></div>${lcFrameGeom(m).adj ? '<p class="note" style="margin:0;color:#b45309">Widened: the set width would make the frame more than 1.2 × taller than wide.</p>' : ''}`}
      ${f.t === 'ring' ? '' : `<div class="grid2">${num('Gap between luminaires m', 'lcm_fdx', f.dx ?? 0.8, 'min="0.3" step="0.05"')}${num('Gap between rows m', 'lcm_fdy', f.dy ?? 0.9, 'min="0.3" step="0.05"')}</div>`}
      <div class="grid2">${selectF('When the mast moves', 'lcm_lock', m.lock ?? 'field', [['field', 'Aim points stay on the field (locked)'], ['mast', 'Aiming moves with the mast'], ['auto', 'Re-aim automatically']])}${num('Frame faces ° (blank = the centre)', 'lcm_az', m.az != null ? Math.round((m.az * 180) / Math.PI) : '', 'step="1"')}</div>
      <div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" id="lcm_aim">Aim this mast</button><button class="btn" id="lcm_del" style="color:var(--bad)">Remove the mast</button><button class="btn" id="lc_done">Done</button></div>
      <div class="tablewrap" style="margin-top:6px"><table class="sch"><thead><tr><th>#</th><th>Aim x / y</th><th>Tilt°</th><th></th></tr></thead><tbody>${m.lights.map((l, k) => { const q = lcQ(L, sel.i, k); return `<tr${sel.k === k ? ' style="background:rgba(200,16,46,.08)"' : ''}><td>${k + 1}</td><td class="m">${l.ax.toFixed(1)} / ${l.ay.toFixed(1)}</td><td class="m" style="color:${q.tilt > 70 ? 'var(--bad)' : 'inherit'}">${q.tilt.toFixed(0)}</td><td><button class="btn" data-lcl="${k}">Select</button></td></tr>`; }).join('')}</tbody></table></div></details>`;
    if (sel.k != null && m.lights[sel.k]) { const l = m.lights[sel.k], q = lcQ(L, sel.i, sel.k);
      h += `<details open><summary><b>Luminaire ${sel.k + 1} on ${esc(m.name)}</b></summary>${lcScLumSel(L, m, l)}<div class="grid2">${num('Aim x m', 'lcl_x', l.ax, 'step="0.5"')}${num('Aim y m', 'lcl_y', l.ay, 'step="0.5"')}</div><div class="grid2">${num('Rotate about the beam °', 'lcl_sp', l.spin ?? 0, 'step="5"')}${selectF('Luminaire type', 'lcl_lum', l.lum ?? '', [['', 'As the mast'], ...lumOpts])}</div><p class="note" style="margin:0">Tilt ${q.tilt.toFixed(1)}° from vertical${q.tilt > 70 ? ' – steeper than 70°, glare' : ''} · drag the red end on the plan to re-aim.</p><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" id="lcl_del" style="color:var(--bad)">Remove this luminaire</button><button class="btn" id="lcl_x2">Done</button></div></details>`; } }
  if (sel?.t === 'c' && L.cams[sel.i]) { const c = L.cams[sel.i];
    h += `<details open id="lcSelBox"><summary><b>Camera C${sel.i + 1}</b></summary>${lcCamNote(L, c)}${field('Name', 'lcc_n', c.n, 'text')}<div class="grid2">${num('x m', 'lcc_x', c.x, 'step="0.5"')}${num('y m', 'lcc_y', c.y, 'step="0.5"')}</div><div class="grid2">${num('Height z m', 'lcc_z', c.z, 'min="0" step="0.5"')}${selectF('Camera', 'lcc_main', c.main ? '1' : '0', [['1', 'Main'], ['0', 'Secondary']])}</div><label class="f chk"><input type="checkbox" id="lcc_on" ${c.on !== false ? 'checked' : ''}> Include in the calculation</label><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" id="lcc_del" style="color:var(--bad)">Remove the camera</button><button class="btn" id="lc_done">Done</button></div></details>`; }
  const so = { ...Object.fromEntries(LC_SEND.map(([k]) => [k, true])), ...(L.sendOpt ?? {}) }, ls = EL.stad?.lcSent;
  h += `<details open id="lcSendD" style="border:1.5px solid var(--ink);border-radius:10px;padding:6px 10px;margin:8px 0"><summary><b>⇢ Send to the electrical design</b>${ls ? ` <span class="note">– sent ${new Date(ls.at).toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' })}</span>` : ''}</summary><p class="note" style="margin:0 0 4px">The masts go to Cable distribution → Stadium layout, and from there to the cable plan (circuits, drivers, breakers, panels), Poles & masts (the mast structure) and earthing / LPS. Choose what to send:</p>
    ${LC_SEND.map(([k, t]) => `<label class="f chk"><input type="checkbox" data-lcso="${k}" ${so[k] ? 'checked' : ''}> ${esc(t)}</label>`).join('')}
    ${lcRoomPlanHtml(L)}<button class="btn" id="lc_to" style="background:var(--ink);color:var(--bg);margin-top:4px">Send to the electrical design</button>${ls ? `<p class="note" style="margin:4px 0 0">Last sent: ${new Date(ls.at).toLocaleString('en-GB', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' })} – ${ls.n} masts, ${ls.N} floodlights, ${ls.kW} kW (${esc(ls.what.join(', '))}). Sending again replaces it.</p>` : ''}</details>`;
  const std = LC_STD[L.std] ?? LC_STD.custom;
  h += `<details${sel ? '' : ' open'}><summary><b>Standard & targets</b></summary>${selectF('Standard', 'lc_std', L.std, Object.entries(LC_STD).filter(([k, v]) => k === 'custom' || (v.sport ?? 'cricket') === (L.sport ?? 'cricket')).map(([k, v]) => [k, v.name]))}${L.std === 'custom' ? field('Name / code of the specification', 'lc_stdn', L.stdName ?? '', 'text') : `<p class="note" style="margin:0">${esc(std.code)} – ${esc(std.note)}</p>`}
    <div class="tablewrap"><table class="sch"><thead><tr><th>Area</th><th>Eh lx</th><th>Ecam lx</th><th>U1</th><th>U2</th></tr></thead><tbody>${LC_AREAS.map(([a, n]) => `<tr><td>${n}</td>${['Eh', 'Ec', 'U1', 'U2'].map((k) => `<td><input type="number" step="any" data-lct="${a}:${k}" value="${L.tg[a]?.[k] ?? ''}" style="width:64px"></td>`).join('')}</tr>`).join('')}</tbody></table></div>${L.std !== 'custom' ? '<button class="btn" id="lc_stdreset">Back to the standard values</button>' : ''}<div class="grid2" style="margin-top:6px">${num('Maintenance factor (MF)', 'lc_mf', L.mf, 'min="0.5" max="1" step="0.01"')}<p class="note" style="margin:0;align-self:end">Results are maintained values: initial lux × MF. LED floodlights usually 0.8 (L80 at the end of life, clean optics); 0.7–0.75 for dusty sites or long cleaning intervals.</p></div>${lcReflHtml(L, num)}</details>`;
  const B = lcBest(L), RS = lcRuleSummary(L);
  h += `<details${RS.some((r) => !r[1]) ? ' open' : ''}><summary><b>Mast rules – ${esc(lcSport(L).name.toLowerCase())}</b> ${RS.every((r) => r[1]) ? '<span style="color:var(--ok)">✓</span>' : `<span style="color:var(--bad)">⚠ ${RS.filter((r) => !r[1]).length}</span>`}</summary>${selectF('When a move breaks a rule', 'lc_rule', L.rule ?? 'block', [['block', 'Block the move'], ['warn', 'Allow it, with a warning']])}
    <div class="grid2">${lcShape(g) === 'oval' ? `${num('Forbidden zone ± ° (from the wicket area edges)', 'lcg_fz', g.fz, 'min="0" max="45"')}<p class="note" style="margin:0;align-self:end">The zone opens from the ends of the wicket area (${2 * g.wA} × ${2 * g.wB} m) – the pitch may be laid anywhere in it. Set the wicket area under Ground.</p>` : g.shape === 'track' ? '<p class="note" style="margin:0">Athletics: masts outside the track, clear of the finish-line view.</p>' : `${num('No-mast zone: half-width m', 'lcg_wB', g.wB, 'min="0" step="0.1"')}${num('Opening ± °', 'lcg_fz', g.fz, 'min="0" max="45"')}<p class="note" style="margin:0;grid-column:1 / -1">${esc(lcSport(L).zoneSet ?? 'Behind each end: 0 m and 0° = no zone.')} 0 and 0 = no zone.</p>`}</div>${num(`${lcSport(L).pole === 'P' ? 'Poles' : 'Masts'} at least … m beyond the ${lcShape(g) === 'oval' ? 'boundary' : lcShape(g) === 'track' ? 'track' : 'run-off'}`, 'lcg_clr', g.clr ?? 5, 'min="0" max="40" step="0.5"')}
    <div style="margin:4px 0">${RS.map(([t, ok2]) => `<div style="color:${ok2 ? 'var(--ok)' : 'var(--bad)'}">${ok2 ? '✓' : '⚠'} ${esc(t)}</div>`).join('')}</div>
    <p class="note" style="margin:0">Green band on the plan: where masts may stand. ★ best ${B.n}-mast positions ${B.rule ? '– by the rules (symmetrical, end masts just outside the forbidden zone); <b>Place the masts automatically</b> tries layouts and marks the best one' : `– the best of ${L.bestFound.tried} layouts tried: ${lcLayTxt(L, B)}`}. Tap a ★ to move the selected mast there, or to add a mast. ${lcShape(g) === 'oval' ? 'Rules from the LiDAC cricket specification: masts outside the forbidden zone, measured from the edges of the wicket area (the pitch may be laid anywhere in it), at least 6 masts, aiming within 70°, symmetrical lighting.' : `Rules: ${lcSport(L).pole === 'P' ? 'poles' : 'masts'} outside the playing area and run-off${lcNoZone(g) ? '' : ` and the ${esc(lcSport(L).zoneS ?? 'no-mast zone')}`}, at least ${lcSport(L).minM ?? 4}, aiming within 70°, symmetrical lighting (EN 12193 practice).`}</p></details>`;
  h += lcHmHtml(L);
  h += `<details><summary><b>Luminaires (IES / LDT)</b></summary><label class="f">Upload IES or LDT files<input type="file" id="lc_file" accept=".ies,.IES,.ldt,.LDT" multiple></label>
    <div class="tablewrap"><table class="sch"><thead><tr><th title="Use in the automatic design">Auto</th><th>Luminaire</th><th>klm</th><th>W</th><th></th></tr></thead><tbody>${Object.entries(L.lums).map(([id, p]) => `<tr><td><input type="checkbox" data-lcuse="${id}" ${lcUseIds(L).includes(id) ? 'checked' : ''}></td><td>${id === L.lum ? '<b>★ </b>' : ''}${esc(p.name)}<br><small>${esc(p.make)} · type ${p.type}${p.file ? ' · ' + esc(p.file) : ''}</small></td><td class="m">${Math.round(p.lm / 1000)}</td><td class="m">${p.W}</td><td><button class="btn" data-lcdef="${id}">Use</button>${p.demo ? '' : `<button class="btn" data-lcdel="${id}" style="color:var(--bad)">✕</button>`}</td></tr>`).join('')}</tbody></table></div><p class="note" style="margin:0">Auto ticked: the luminaires the automatic design may use – it tries each alone and, with two or more, a mix (the best type for each aim), and keeps the passing design with the lowest masts and fewest floodlights. ★ the project luminaire; a mast or a single luminaire can use another. The demo floodlights are generic, for trying the tool – use the maker’s file for the real design.</p></details>`;
  h += lcRfHtml(L);
  h += lcChkHtml(L);
  h += `<details${EL.stad?.on ? ' open' : ''}><summary><b>Masts</b>${lcLinked() ? ' <span class="note">– follow the stadium layout</span>' : ''}</summary>${EL.stad?.on ? `<label class="f chk"><input type="checkbox" id="lc_link" ${EL.stad.lcLink !== false ? 'checked' : ''}> Masts follow the stadium layout in Cable distribution (positions, heights, floodlights – updated whenever it changes there)</label>` : '<p class="note" style="margin:0 0 4px">Place the stadium layout in Cable distribution and its masts come here automatically.</p>'}<div class="grid2">${selectF('Number of masts', 'lc_nm', L.masts.length, [[4, '4'], [6, '6'], [8, '8'], [10, '10']])}${num('Luminaires per mast', 'lc_np', L.masts[0]?.lights.length ?? 16, 'min="1" step="1"')}</div><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" id="lc_gen">Place round the boundary</button><button class="btn" id="lc_add">+ Mast</button><button class="btn" id="lc_from">Take from the stadium layout</button></div>
    <div class="tablewrap"><table class="sch"><thead><tr><th>Mast</th><th>x / y m</th><th></th></tr></thead><tbody>${L.masts.map((m, i) => `<tr><td><b>${esc(m.name)}</b></td><td class="m">${m.x} / ${m.y}</td><td><button class="btn" data-lcsm="${i}">Open</button></td></tr>`).join('')}</tbody></table></div></details>`;
  h += `<details><summary><b>Cameras</b> <button type="button" class="hlpx" id="lc_caminfo" aria-label="Camera placement and standards">i</button></summary><div class="tablewrap"><table class="sch"><thead><tr><th>Camera</th><th>x / y / z</th><th title="Included in the calculation">In calc.</th><th></th></tr></thead><tbody>${L.cams.map((c, i) => `<tr style="${c.on === false ? 'color:var(--mut, #7a868b)' : ''}"><td><b>C${i + 1}</b> ${esc(c.n)}<br><small>${c.main ? 'main' : 'secondary'}${c.moved ? ' · <b style="color:var(--bad)">⚠ moved from the standard position</b>' : ''}</small></td><td class="m">${c.x} / ${c.y} / ${c.z}</td><td style="text-align:center"><input type="checkbox" data-lcon="${i}" ${c.on !== false ? 'checked' : ''} aria-label="Include C${i + 1} in the calculation" style="width:18px;height:18px"></td><td><div style="display:flex;gap:4px;flex-wrap:wrap;justify-content:flex-end"><button class="btn" data-lcsc="${i}">Open</button>${c.moved && lcCamDef(L, c) ? `<button class="btn" data-lccback="${i}" title="Put C${i + 1} back to its standard / best-practice position" style="color:var(--bad);border-color:var(--bad)">↺ Standard position</button>` : ''}</div></td></tr>`).join('')}</tbody></table></div><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" id="lc_cadd">+ Camera</button><button class="btn" id="lc_cdef">Standard cameras</button>${L.cams.filter((c) => c.moved && lcCamDef(L, c)).length > 1 ? `<button class="btn" id="lc_cball" style="color:var(--bad);border-color:var(--bad)">↺ All ${L.cams.filter((c) => c.moved && lcCamDef(L, c)).length} moved cameras back</button>` : ''}</div></details>`;
  h += `<details id="lc_gdet"${LCGOPEN || LCOSM.open || L.under || ['mk', 'cal', 'under'].includes(LCMODE) ? ' open' : ''}><summary><b>Ground, grid & drawing</b></summary>${lcShape(g) !== 'oval' ? lcGroundHtml(L, num) : `<div class="grid2">${num('Boundary half-length m (along the pitch)', 'lcg_Rx', g.Rx, 'min="40" max="100"')}${num('Boundary half-width m', 'lcg_Ry', g.Ry, 'min="40" max="100"')}</div>
    ${selectF('Wicket area shape', 'lcg_wShape', g.wShape ?? 'rect', [['rect', 'Rectangle (equal sizes = a square)'], ['ellipse', 'Ellipse']])}<div class="grid2">${num('Wicket area half-length m (along the pitch)', 'lcg_wA', g.wA, 'min="11" step="0.5"')}${num('Wicket area half-width m', 'lcg_wB', g.wB, 'min="2" step="0.5"')}</div><p class="note" style="margin:0">Wicket area ${2 * g.wA} × ${2 * g.wB} m${(g.wShape ?? 'rect') === 'rect' ? (g.wA === g.wB ? ' (square)' : ' (rectangle)') : ' (ellipse)'} round the centre of the pitch.</p>${num('30-yard circle radius m', 'lcg_inR', g.inR, 'min="20" step="0.01"')}`}
    ${selectF('Calculation grid', 'lc_gridm', L.grid ?? 'area', LC_GRIDM)}${L.grid === 'pts' ? lcEvGrid(L).grids.map((q) => `<div class="grid2">${num(`${esc(lcAreaNm(q.grid))} – points X`, `lc_gp_${q.grid}_x`, q.nx, 'min="1" max="200" step="1"')}${num('points Y', `lc_gp_${q.grid}_y`, q.ny, 'min="1" max="200" step="1"')}</div>`).join('') : L.grid !== 'fixed' ? `<p class="note" style="margin:0">${lcEvGrid(L).grids.map((q) => `${esc(lcAreaNm(q.grid))} ${q.nx} × ${q.ny}`).join(' · ')}</p>` : ''}${num(L.grid === 'fixed' ? 'Grid spacing m' : 'Map grid m', 'lc_s', L.s, 'min="1" max="10" step="0.5"')}<div class="grid2">${num('Ecam height m', 'lc_hc', L.hc, 'min="0" step="0.1"')}${selectF('Camera plane', 'lc_plane', L.plane, [['vert', 'Vertical, facing the camera'], ['face', 'Square to the camera (3D)']])}</div>
