  return h;
}
function lcBind(L) {
  const re = (calc = true) => { if (calc) lcInvalidate(); renderLc(); };
  const ch = (id, fn, calc = true) => { const i = $('#' + id); if (i) i.addEventListener('change', () => { if (calc) lcSnap(L, `change of ${lcLabel(i, id)}`); fn(i.type === 'checkbox' ? i.checked : i.value); if (calc) lcSnapDrop(L); re(calc); }); };
  const clk = (id, fn) => $('#' + id)?.addEventListener('click', fn);
  ch('lc_ucalc', (v) => (L.underCalc = v), false); ch('lc_udk', (v) => { if (L.under) L.under.dk = v; }, false); ch('lc_uon', (v) => { if (L.under) L.under.off = !v; }, false);
  $('#lc_sport')?.addEventListener('change', (e) => { if (L.sportSet) return; lcSnap(L, 'change of sport'); lcSetSport(L, e.target.value); L.sportSet = true; LCMSG = `${lcSport(L).name}: ground, standard (${LC_STD[L.std]?.name ?? 'custom'}), cameras and ${lcSport(L).pole === 'P' ? 'poles' : 'masts'} set – press Complete the design automatically. ↶ Undo goes back.`; renderLc(); }); lcGroundBind(L, ch);
  ch('lc_view', (v) => (L.view = v), false); ch('lc_iso', (v) => (L.iso = v), false); ch('lc_best', (v) => (L.best = v), false); ch('lc_rule', (v) => (L.rule = v), false);
  clk('lc_place', async () => { if (LCBUSY) return; if (L.fixPos) { LCMSG = 'Mast locations are fixed – choose “May change” to place the masts again.'; re(false); return; } const n = +$('#lc_pn').value || 6; lcSnap(L, 'automatic mast placement'); const RB = lcRunBegin(L); LCBUSY = 'place'; renderLc(); const b = await lcPlace(L, n, (k, t) => { const b2 = $('#lc_place'); if (b2) b2.textContent = `Placing… layout ${k} of ${t}`; }); LCBUSY = false; LCSEL = null; lcRunEnd(L, 'Place the masts automatically', RB); LCMSG = `${n} masts placed – the best of ${L.bestFound.tried} layouts: end masts ${b.a0}° from the pitch axis, ${b.off} m beyond the boundary, ${Math.round(b.H)} m high, ${L.masts[0].lights.length} floodlights each, aimed. Now optimise the aiming.`; re(); }); ch('lc_aimshow', (v) => (L.aimShow = v), false);
  clk('lc_undo', () => { lcUndo(L); renderLc(); });
  clk('lc_gosend', () => { const d = $('#lcSendD'); if (d) { d.open = true; d.scrollIntoView({ behavior: 'smooth', block: 'start' }); } });
  document.querySelectorAll('#lcInsp [data-lcopt]').forEach((b) => b.addEventListener('click', () => { const i = +b.dataset.lcopt, r = L.autoCmp[i]; if (!LCOPTS[i]) return; lcSnap(L, `viewing option ${i + 1}`); Object.assign(L, JSON.parse(LCOPTS[i])); L.autoShown = i; LCSEL = null; lcInvalidate(); LCMSG = `Showing option ${i + 1}: ${r.name} – ${r.fails ? `${r.fails} checks to fix` : 'every check passes'}, ${r.N} floodlights, masts ${r.H} m.${lcLinked() ? ' Press “Send to the electrical design” to use it there.' : ''}`; renderLc(); }));
  $('#lc_fs')?.addEventListener('click', () => lcFullSet(!LCFULL)); $('#lc_fsx')?.addEventListener('click', () => lcFullSet(false));
  const lcRdfOpen = async (f) => { LCMSG = `Reading ${f.name}…`; renderLc(); try { LCMSG = await rdfImport(f); ZOOM.lcSvg = null; } catch (err) { LCMSG = `The Relux project could not be imported: ${err?.message ?? err}`; try { window.alert(LCMSG); } catch (e) { void e; } } renderLc(); }; // the message shows above the plan, often scrolled out of view – an alert as well
  $('#lc_rdfin')?.addEventListener('change', (e) => { const f = e.target.files?.[0]; if (!f) return; if (!L.sportSet) { LCRDFQ = f; renderLc(); return; } void lcRdfOpen(f); }); // a new design asks which sport the Relux project is for
  $('#lc_rdfgo')?.addEventListener('click', () => { const f = LCRDFQ, v = $('#lc_rdfsp')?.value; LCRDFQ = null; if (!f) return; lcSnap(L, 'change of sport'); if (v && v !== (L.sport ?? 'cricket')) lcSetSport(L, v); L.sportSet = true; void lcRdfOpen(f); });
  $('#lc_rdfno')?.addEventListener('click', () => { LCRDFQ = null; renderLc(); });
  const rdfGo = async (f) => { LCMSG = 'Writing the Relux project…'; renderLc(); try { const r = await rdfWrite(L, f); LCMSG = `${r.name} made – ${r.n} luminaires moved and re-aimed${r.nCam ? `, ${r.nCam} camera positions updated` : ''}; Relux recalculates the results when it opens. Experimental: check the scene in Relux before relying on it.`; } catch (err) { LCMSG = `The Relux project could not be written: ${err?.message ?? err}`; } renderLc(); };
  $('#lc_rdfnew')?.addEventListener('click', () => lcGridPop(L, async () => { LCMSG = 'Making the Relux project…'; renderLc(); try { const r = await rdfNew(L); rdfSave(r.name, r.bytes); LCMSG = `${r.name} made – ${r.n} floodlights with their aiming, photometry ${r.lum}${r.others ? ` (${r.others} floodlights of other types use it too – one luminaire type per project for now)` : ''}, ground ${r.W} × ${r.H} m, ${r.nCam} camera${r.nCam === 1 ? '' : 's'}, ${r.planes.length > 1 ? `measuring surfaces ${r.planes.map((x) => `“${x}”`).join(', ')}` : `the measuring plane “${r.plane}”`}; the aiming points are where the beams meet the ground. The field centre is at x ${r.ox} / y ${r.oy} m in Relux – Export plan .dxf gives the ground drawing at the same place. Relux applies its own maintenance factor (its maintenance plan) – check it is ${L.mf} as in this design. Experimental: check the scene in Relux.`; } catch (err) { LCMSG = `The Relux project could not be made: ${err?.message ?? err}`; } renderLc(); }));
  $('#lc_dxf')?.addEventListener('click', () => { try { const s = lcDxf(L), nm = `${String((typeof SITE !== 'undefined' && SITE?.name) || 'Light calc').replace(/[\\/:*?"<>|]+/g, '-').slice(0, 80)} – DIMO plan.dxf`; rdfSave(nm, new TextEncoder().encode(s)); const { ox, oy } = rdfFrame(L); LCMSG = `${nm} made – in Relux import it as a CAD plan at 0 / 0 (metres); the field centre is at x ${ox} / y ${oy} m, the same as in Export new .rdf.`; } catch (err) { LCMSG = `The plan could not be made: ${err?.message ?? err}`; } renderLc(); });
  $('#lc_rdfout')?.addEventListener('click', () => (RDF_LAST ? rdfGo(null) : $('#lc_rdfpick')?.click())); $('#lc_rdfpick')?.addEventListener('change', (e) => { const f = e.target.files?.[0]; if (f) rdfGo(f); });
  $('#lc_relux')?.addEventListener('click', async () => { try { await rxExport(L); } catch (err) { LCMSG = `The Relux pack could not be made: ${err?.message ?? err}`; } renderLc(); }); $('#lc_pdf')?.addEventListener('click', async (e) => { await lcPdf(L, 'full', e.currentTarget); renderLc(); }); $('#lc_pdfaim')?.addEventListener('click', async (e) => { await lcPdf(L, 'aim', e.currentTarget); renderLc(); }); $('#lc_pdfpts')?.addEventListener('click', async (e) => { await lcPdfPts(L, e.currentTarget); renderLc(); }); $('#lc_ptpaper')?.addEventListener('change', (e) => { L.ptPaper = e.target.value; });
  ch('lc_link', (v) => { EL.stad = { ...(EL.stad ?? {}), lcLink: v }; if (v) L.stadSig = null; else LCMSG = 'Masts unlinked – move them here freely; “Send to the electrical design” updates Cable distribution.'; }, false);
  clk('lc_auto', async () => { if (LCBUSY) return; lcSnap(L, 'the automatic design'); const RB = lcRunBegin(L); LCBUSY = 'auto'; LCSEL = null; renderLc(); const b0 = () => $('#lc_auto'); try { LCMSG = await lcAutoAll(L, +($('#lc_pn')?.value) || 6, (t) => { const b = b0(); if (b) b.textContent = `Designing… ${t}`; }); } catch (er) { LCMSG = `Stopped: ${er.message || er}`; } LCBUSY = false; lcRunEnd(L, 'Complete the design automatically', RB); lcInvalidate(); renderLc(); });
  const allH = (f) => lcPoles(L).forEach((m) => (m.h = lcHclamp(L, Math.max(5, Math.min(80, Math.round(f(m.h) * 2) / 2))))), allN = (f) => L.masts.forEach((m) => lcSetCount(L, m, f(m.lights.length)));
  ch('lc_allh', (v) => { if (v !== '') { allH(() => +v); LCMSG = `All masts set to ${+v} m – aim points kept.`; } }); ch('lc_alln', (v) => { if (v !== '') { allN(() => +v); LCMSG = `${+v} floodlights on every mast – the aiming kept; optimise the aiming next.`; } });
  document.querySelectorAll('#lcInsp [data-lcadj]').forEach((b) => b.addEventListener('click', () => { const [k, v] = b.dataset.lcadj.split(':'); lcSnap(L, b.textContent.trim()); if (k === 'h') allH((x) => x + +v); else if (v.endsWith('%')) allN((x) => Math.ceil(x * (1 + parseFloat(v) / 100))); else allN((x) => x + +v); LCMSG = `${b.textContent.trim()} – done; optimise the aiming next.`; re(); }));
  document.querySelectorAll('#lcInsp [data-lcmh]').forEach((i) => i.addEventListener('change', () => { const m = L.masts[+i.dataset.lcmh]; lcSnap(L, `height of ${m.name}`); m.h = Math.max(5, Math.min(80, +i.value || m.h)); lcSnapDrop(L); re(); }));
  document.querySelectorAll('#lcInsp [data-lcmn]').forEach((i) => i.addEventListener('change', () => { const m = L.masts[+i.dataset.lcmn]; lcSnap(L, `floodlights on ${m.name}`); lcSetCount(L, m, +i.value || m.lights.length); lcSnapDrop(L); re(); }));
  const fix = async (andOpt) => { const FX = lcFix(L, lcResults(L)); if (!FX) return; lcSnap(L, 'the suggestion'); L.masts.forEach((m, i) => { m.h = m.roof ? m.h : FX.H[i]; lcSetCount(L, m, FX.N[i]); }); lcClampAll(L); LCMSG = `Suggestion applied: ${FX.N.reduce((t, v) => t + v, 0)} floodlights${FX.up ? ', masts raised' : ''}.`; lcInvalidate(); if (andOpt) await opt(false); else re(); };
  clk('lc_fix', () => fix(false)); clk('lc_fixopt', () => fix(true));
  clk('lc_sug', () => { lcSnap(L, 'suggested heights & count'); const RB = lcRunBegin(L); const S = lcSuggest(L); L.masts.forEach((m, i) => { m.h = m.roof ? m.h : S.H[i]; const n = S.perR; while (m.lights.length < n) m.lights.push({ ax: 0, ay: 0 }); m.lights.length = n; lcAimInit(L, m); }); lcRunEnd(L, 'Apply the suggested heights & count', RB); LCMSG = `Heights set, ${S.perR} luminaires per mast, aimed – now optimise the aiming.`; re(); });
