// what the last automatic run changed (the option kept against the design before it): masts moved, heights, floodlights added / removed, re-aimed
function lcAutoStats(A, L, b, linked, opts) { const M0 = A.masts ?? [], M1 = L.masts, mv = (p, q) => !p || Math.hypot(p.x - q.x, p.y - q.y) > 0.05;
