  let aimed = 0; M1.forEach((m, i) => m.lights.forEach((l, k) => { const o = M0[i]?.lights?.[k]; if (!o || Math.hypot(o.ax - l.ax, o.ay - l.ay) > 0.05) aimed++; }));
