  if (rm.kind === 'outdoor') { const L = r1d((Wt + 200) / 1000), D = r1d((Dm + 250) / 1000), H = r1d((Hm + 400) / 1000); return { outdoor: true, L, D, H, padL: r1d(L + 1.0), padD: r1d(D + 1.0 + 0.3), Wt, acb, Q, n: ps.length }; }
  const front = acb ? 1500 : 1200, rear = rm.rear ? 800 : 0; return { outdoor: false, L: r1d((Wt + 2000) / 1000), D: r1d((Dm + front + rear) / 1000), H: r1d(Math.max(3, (Hm + 600) / 1000)), front, rear, Wt, acb, Q, n: ps.length }; }
function roomSizeTxt(nm) { const rm = SITE.rooms?.[nm] ?? {}, d = roomDims(nm), data = rm.data !== false;
  if (d.outdoor) return `Outdoor panel: kiosk ≈ ${d.L} × ${d.D} × ${d.H} m (W × D × H) for ${d.n} panel section${d.n === 1 ? '' : 's'}, IP55 or better, canopy, anti-condensation heater, filtered fans (${Math.round(d.Q)} W heat${d.Q > 3000 ? ' – too much for a kiosk: put the drivers at the mast base, or use a ventilated / air-conditioned room' : ''}), SPD T2; on a concrete plinth ${d.padL} × ${d.padD} m with 1 m clear working space in front (BS 7671 729.513.2.1 ≥ 700 mm); ${data ? 'data: a separate network compartment (DMX / Ethernet nodes, fibre in)' : 'no data – control by timer / photocell in the kiosk'}.`;
  return `Panel room ≈ ${d.L} × ${d.D} m, ${d.H} m clear height: ${d.n} panel${d.n === 1 ? '' : 's'} in line (${(d.Wt / 1000).toFixed(1)} m) + 1.0 m each end, ${d.front} mm in front${d.rear ? ` and ${d.rear} mm behind` : ''} (BS 7671 729.513.2.1)${d.L > 6 ? ', two exits (line-up over 6 m)' : ''}; heat ${Math.round(d.Q)} W; ${data ? 'data: network rack / DMX nodes in the room' : 'no data – control by timer / photocell'}.`; }
// the rooms on the stadium cable plan – drag one to move it; its feeders and the masts it feeds are re-routed round the trench
function stadUnder() { const s = stadUnder0(); if (!s || !EL.stad?.on) return s; let g = ''; try { g = ghostsUnder(); } catch (e) { g = ''; } try { return s + g + roomsUnder(); } catch (e) { return s + g; } }
// masts fed from another board: drawn grey on this plan with the board that feeds them – tap one to open that board's plan
function ghostsUnder() { const o = stadOpt(), pil = net.N.find((n) => n.type === 'pillar'), P0 = stadPillar(o), k = 1 / (net.scale || 1), X = (x) => pil.x + (x - P0.x) * k, Y = (y) => pil.y + (y - P0.y) * k; let s = '';
  stadMasts().forEach((m) => { const f = stadFeedOf(m.i); if (!f || f === net.link) return; const bn = (findNode(f)?.n?.name ?? '').split(' ')[0], x = X(m.x), y = Y(m.y);
    s += `<g data-ghost="${esc(f)}" style="cursor:pointer"><circle cx="${x}" cy="${y}" r="8" fill="#fff" stroke="#9AA5AB" stroke-width="2" stroke-dasharray="3 2"/><line x1="${x - 4}" y1="${y}" x2="${x + 4}" y2="${y}" stroke="#9AA5AB" stroke-width="1.5"/><text x="${x}" y="${y - 12}" text-anchor="middle" font-size="10" font-weight="700" fill="#7A858B">${esc(m.name)}</text><text x="${x}" y="${y + 19}" text-anchor="middle" font-size="9" fill="#7A858B">fed from ${esc(bn)} – tap</text></g>`; });
  return s; }
$('#net')?.addEventListener('pointerdown', (e) => { const g = e.target.closest?.('[data-ghost]'); if (!g || !EL.stad?.on) return; e.stopPropagation(); e.preventDefault(); const f = g.dataset.ghost; if (findNode(f)) openNet(f); }, true);
function roomsUnder() { const o = stadOpt(), pil = net.N.find((n) => n.type === 'pillar'), P0 = stadPillar(o), k = 1 / (net.scale || 1), X = (x) => pil.x + (x - P0.x) * k, Y = (y) => pil.y + (y - P0.y) * k; let s = '';
  const mnR = Object.entries(SITE.rooms ?? {}).find(([, r]) => r.main && r.with)?.[1];
