    s += `<g data-room="${esc(nm)}" style="cursor:move;touch-action:none"><rect x="${X(p.x) - w / 2}" y="${Y(p.y) - h / 2}" width="${w}" height="${h}" rx="2" fill="${c}" fill-opacity=".16" stroke="${c}" stroke-width="2"${d.outdoor ? ' stroke-dasharray="5 3"' : ''}/><text x="${X(p.x)}" y="${Y(p.y) - h / 2 - 5}" font-size="11" text-anchor="middle" font-weight="700" fill="${c}" stroke="#fff" stroke-width="3" paint-order="stroke">${esc(nm)}${mnR?.with === nm ? ' + main panels' : ''}${d.outdoor ? ' · outdoor' : ''}${rm.data === false ? ' · no data' : ''}</text></g>`; });
