    const mark = (x, yb, good) => { J.setDrawColor(...(good ? ok : bad)); J.setLineWidth(0.4); if (good) { J.line(x, yb - 1.2, x + 0.8, yb - 0.3); J.line(x + 0.8, yb - 0.3, x + 2.4, yb - 2.4); } else { J.line(x + 0.2, yb - 2.2, x + 2.1, yb - 0.3); J.line(x + 2.1, yb - 2.2, x + 0.2, yb - 0.3); } J.setLineWidth(0.2); };
