    const symV = (cx, cy, a, ux, uy) => { J.setDrawColor(...blue); J.setLineWidth(Math.max(0.12, a * 0.11)); const x1 = cx - ux * a, y1 = cy - uy * a, x2 = cx + ux * a, y2 = cy + uy * a, h = a * 0.6, c = Math.cos(2.6), s = Math.sin(2.6); J.line(x1, y1, x2, y2); J.line(x2, y2, x2 + h * (ux * c - uy * s), y2 + h * (ux * s + uy * c)); J.line(x2, y2, x2 + h * (ux * c + uy * s), y2 + h * (-ux * s + uy * c)); };
