      J.setLineDashPattern([1.2, 1], 0); const ir = g.inR, sx = g.sx; J.line(px(-sx), py(ir), px(sx), py(ir)); J.line(px(-sx), py(-ir), px(sx), py(-ir)); [[sx, 1], [-sx, -1]].forEach(([c0, sg]) => { let prev = null; for (let a = -90; a <= 90; a += 6) { const t = (a * Math.PI) / 180, P = [px(c0 + sg * ir * Math.cos(t)), py(ir * Math.sin(t))]; if (prev) J.line(prev[0], prev[1], P[0], P[1]); prev = P; } }); J.setLineDashPattern([], 0);
      J.setDrawColor(...ink); J.setLineWidth(0.35); if ((g.wShape ?? 'rect') === 'rect') J.rect(px(-g.wA), py(g.wB), 2 * g.wA * k, 2 * g.wB * k, 'S'); else J.ellipse(px(0), py(0), g.wA * k, g.wB * k, 'S'); J.setFillColor(214, 196, 160); J.rect(px(-10.06), py(1.5), 20.12 * k, 3 * k, 'F'); }
      pts.forEach((i) => { const p = R.pts[i], X = px(p.x), Y = py(p.y), v = String(Math.round(q.arr[i])), big = cm >= 2.4;
        J.setFont('helvetica', 'bold'); J.setFontSize(F.fs); J.setTextColor(...ink); J.text(F.withSym ? `${q.sym} ${v}` : v, X, big ? Y + F.fs * 0.3528 * 0.15 - cm * 0.08 : Y + F.fs * 0.3528 * 0.35, { align: 'center' });
