      const tx = T(`vertical plane facing the camera (Ev) – the arrow points to the camera. ${note} Cell colour: the value against the highest on the sheet. Masts: black dots; cameras: triangles (this sheet's camera in red). ${stdName}.`); const ln = J.splitTextToSize(tx, W - M - x); J.text(ln[0], x, y); if (ln[1]) J.text(J.splitTextToSize(tx.slice(ln[0].length).trim(), W - 2 * M)[0], M, y + 3.6); J.setTextColor(...ink); };
