}

// a panel room is never left standing on a mast: one at its standard place within 14 m of a mast slides along its side (dragged rooms stay put)
function roomsClear() { if (!EL.stad?.on) return; const o = stadOpt(); let ms = []; try { ms = stadMasts(); } catch (e) { return; }
  Object.values(SITE.rooms ?? {}).forEach((rm) => { if (rm.x != null || !rm.side) return; const hit = (r) => { const p = roomXY(r, o); return p && ms.some((m) => Math.hypot(m.x - p.x, m.y - p.y) < 25); }; if (!hit(rm)) return;
    const a0 = +rm.along || 0; for (const d of [20, -20, 32, -32, 45, -45, 60, -60]) { if (!hit({ ...rm, along: a0 + d })) { rm.along = a0 + d; return; } } }); }
// a cable plan fed from a driver panel: the drivers sit in the panel room and each floodlight's output runs up the mast in its own cable – the side panel shows
// those driver-output cables (count, cores, size, run, ΔU, length limit), not 4-core feeders
const drvPlanOf = (bd) => (bd?.kids ?? []).filter((k) => k.netDrv && k.netOf === bd.id);
function drvPlanHtml(bd) { const ks = drvPlanOf(bd), out = lastCalc.out; if (!ks.length) return '';
  const rows = ks.map((k) => ({ k, r: out.get(k.id), d: out.get(k.id)?.drv })).filter((x) => x.d), tot = new Map(); let kw = 0;
  rows.forEach(({ k, d }) => { kw += +k.kw || 0; const key = `${d.cores}C ${d.S}`; tot.set(key, (tot.get(key) || 0) + d.cables * d.L); });
  const nm = (k) => (k.name || '').split(' – ')[0], pole = rows.length && rows.every(({ k }) => /^P-\d/.test(nm(k))), W = pole ? ['pole', 'poles', 'Pole'] : ['mast', 'masts', 'Mast'];
  const kv = (t, v, bad) => `<span style="white-space:nowrap"><small style="color:var(--muted)">${t}</small> <b class="m"${bad ? ' style="color:var(--bad)"' : ''}>${v}</b></span>`;
  return `<h3>Driver panel circuits – drivers in the panel room</h3><p class="note">Each floodlight's driver sits in ${esc(bd.name)}; its output runs to the floodlight in its own cable through the trench and up the ${W[0]}. One supply breaker feeds the drivers of each ${W[0]}; the output cables are sized for the drivers' current and voltage drop, and checked against the drivers' longest allowed output run (${esc(rows[0]?.d.src ?? 'panel setting')}).</p>
    <div style="display:flex;flex-direction:column;gap:6px;margin:8px 0">${rows.map(({ k, r, d }) => { const ok = d.okL && d.okV; return `<div style="border:1px solid var(--line);border-left:4px solid var(${ok ? '--ok' : '--bad'});border-radius:8px;padding:6px 9px"><div style="display:flex;justify-content:space-between;gap:8px;align-items:baseline"><b>${esc(nm(k))}</b><span class="m">${d.heads} × ${k.w ?? ''} W · ${r1(+k.kw || 0, 1)} kW</span><b style="color:var(${ok ? '--ok' : '--bad'})">${ok ? '✓' : '✗'}</b></div>
      <div style="display:flex;flex-wrap:wrap;gap:2px 14px;margin-top:3px">${kv('Driver supply', `${esc(r?.dev ?? '')} ${r?.In ?? ''} A`)}${kv('Output cables', `${d.cables} × ${d.cores}C ${d.S} mm²`)}${kv('Run', `${d.L} m${d.okL ? ` (max ${d.Lmax})` : ` > ${d.Lmax} m`}`, !d.okL)}${kv('ΔU', `${r1(d.vd, 1)} %`, !d.okV)}</div></div>`; }).join('')}</div>
    ${rows.some(({ d }) => !d.okL) ? `<div class="ck soft"><b>!</b><span>${rows.filter(({ d }) => !d.okL).map(({ k, d }) => `${esc(nm(k))}: ${d.L} m of driver output is over the drivers' ${d.Lmax} m`).join('; ')} – move the panel room nearer (drag it on the plan), feed the ${W[0]} from the nearer room (Panel rooms), put the drivers at the ${W[0]} base (Stadium layout → drivers), or choose drivers rated for longer runs.</span></div>` : ''}
    <dl class="kv"><dt>Total</dt><dd>${r1(kw, 1)} kW on ${rows.length} ${rows.length === 1 ? W[0] : W[1]}</dd><dt>Cable to order</dt><dd>${[...tot.entries()].map(([c, L]) => `${c} mm² Cu/PVC/SWA/PVC (driver output) ${Math.round(L * 1.05).toLocaleString('en-GB')} m`).join('<br>')}<br><small>run includes the rise up the ${W[0]}; runs × cables, +5 % for slack and terminations; laid in ducts in the cable trench (see Panel rooms → cable trench)</small></dd></dl>`; }
// each mast fed from the nearest HM panel room (along the trench) – re-done on every send and room move, unless the feeds were picked by hand in Panel rooms
function stadNearestFeed() { if (EL.stad?.feedManual) return; const o = stadOpt(); let ms = []; try { ms = stadMasts(); } catch (e) { return; }
  const rooms = prHm().filter((nm) => roomXY(SITE.rooms[nm], o) && prIP(nm)); if (!rooms.length || !ms.length) return;
  const want = (EL.stad?.drv ?? 'room') === 'room' ? 'DRV' : 'OP', feed = { ...(EL.stad?.feed ?? {}) }, load = {};
  ms.forEach((m) => { const nm = rooms.map((r) => [r, trenchLen(o, roomXY(SITE.rooms[r], o), { x: m.x, y: m.y })]).sort((a, b) => a[1] - b[1])[0][0];
    const ps = roomPanels(nm).filter((p) => p.kind === want || (want === 'OP' && p.kind === 'IP' && p.comb?.op)), alt = roomPanels(nm).filter((p) => ['DRV', 'OP'].includes(p.kind) || (p.kind === 'IP' && p.comb?.op)), pool = ps.length ? ps : alt; if (!pool.length) return;
    const p = pool.sort((a, b) => (load[a.id] ?? 0) - (load[b.id] ?? 0))[0]; load[p.id] = (load[p.id] ?? 0) + 1; feed[m.i] = p.id; });
  EL.stad = { ...STAD_DEF, ...(EL.stad ?? {}), feed }; }
// the panel rooms chosen before sending (Lighting calc → Send): each mast its own HM panel room, or 2 / 4 rooms each serving the masts on its side;
// the main panel room separate or combined with one HM panel room. Main → each HM room by its own feeder; each HM room → the floodlights of its masts
const roomPlan = () => ({ mode: 'each', main: 'sep', ...(EL.roomPlan ?? {}) });
const rpCount = (n, mode) => (mode === 'each' ? n : Math.max(1, Math.min(n, +mode || 2)));
function rpGroups(ms, k) { if (k >= ms.length) return ms.map((m) => [m]);
  const s = [...ms].sort((a, b) => Math.atan2(a.y, a.x) - Math.atan2(b.y, b.x)), n = s.length; let best = null;
  for (let r = 0; r < n; r++) { const g = []; let p = 0; for (let j = 0; j < k; j++) { const c = Math.round((n * (j + 1)) / k) - Math.round((n * j) / k); g.push(Array.from({ length: c }, (_, q) => s[(r + p + q) % n])); p += c; }
    const cost = g.reduce((t, gr) => { const cx = gr.reduce((a, m) => a + m.x, 0) / gr.length, cy = gr.reduce((a, m) => a + m.y, 0) / gr.length; return Math.max(t, ...gr.map((m) => Math.hypot(m.x - cx, m.y - cy))); }, 0);
    if (!best || cost < best.c - 1e-6) best = { c: cost, g }; }
  return best.g.sort((a, b) => Math.min(...a.map((m) => m.i)) - Math.min(...b.map((m) => m.i))); }
function stadRoomPlan() { if (!tree?.kids?.[0]) return; let ms = []; try { ms = stadMasts(); } catch (e) { return; } if (!ms.length) return;
  if (!EL.roomPlan && ms.some((m) => (+m.H || 0) < 20)) return; // poles (tennis, pickleball): the shared rooms as before, unless a plan was chosen
  const rp = roomPlan(), k = rpCount(ms.length, rp.mode), sig = `${rp.mode}:${ms.length}`, redo = EL.stad?.rpSig !== sig;
  if (!prMainNm()) prStart(2); const num = (x) => +(/(\d+)\D*$/.exec(x)?.[1] ?? 999), rooms = () => prHm().sort((a, b) => num(a) - num(b));
  let guard = 0; while (rooms().length < k && guard++ < 40) { if (!prAddRoom()) break; }
  const rs = rooms(), want = (EL.stad?.drv ?? 'room') === 'room' ? 'DRV' : 'OP', feed = { ...(EL.stad?.feed ?? {}) };
  rpGroups(ms, k).forEach((gr, j) => { const nm = rs[j], rm = nm && SITE.rooms[nm]; if (!rm) return;
    const cx = gr.reduce((a, m) => a + m.x, 0) / gr.length, cy = gr.reduce((a, m) => a + m.y, 0) / gr.length, ang = Math.atan2(cy, cx), R = Math.max(...gr.map((m) => Math.hypot(m.x, m.y))) + 22;
    if (redo || rm.x == null || rm.autoAt) { rm.x = Math.round(Math.cos(ang) * R); rm.y = Math.round(Math.sin(ang) * R); rm.autoAt = true; }
    rm.side = Math.abs(rm.x) >= Math.abs(rm.y) ? (rm.x >= 0 ? 'E' : 'W') : rm.y >= 0 ? 'S' : 'N'; rm.masts = gr.map((m) => m.name).join(', ');
    const ps = roomPanels(nm).filter((p) => p.kind === want || (want === 'OP' && p.kind === 'IP' && p.comb?.op)), alt = roomPanels(nm).filter((p) => ['DRV', 'OP'].includes(p.kind) || (p.kind === 'IP' && p.comb?.op)), pool = ps.length ? ps : alt;
    if (pool.length && (redo || !EL.stad?.feedHand)) gr.forEach((m, q) => { feed[m.i] = pool[q % pool.length].id; }); });
  EL.stad = { ...STAD_DEF, ...(EL.stad ?? {}), feed, feedManual: true, rpSig: sig, ...(redo ? { feedHand: false } : {}) };
  rs.slice(k).forEach((nm) => { try { prRemoveRoom(nm); } catch (e) { void e; } });
  const mn = prMainNm(), with_ = rp.main !== 'sep' && rooms()[+rp.main - 1]; if (mn) SITE.rooms[mn].with = with_ || null; }
function lcRoomPlanHtml(L) { const n = L.masts.length, rp = roomPlan(), k = rpCount(n, rp.mode), sel = (id, v, o) => `<select id="${id}">${o.map(([a, t]) => `<option value="${a}"${String(a) === String(v) ? ' selected' : ''}>${esc(t)}</option>`).join('')}</select>`;
  const mo = [['each', `Each mast its own HM panel room (${n})`], ...(n > 2 ? [['2', '2 HM panel rooms']] : []), ...(n > 4 ? [['4', '4 HM panel rooms']] : [])], mn = [['sep', 'Separate room'], ...Array.from({ length: k }, (_, i) => [String(i + 1), `With HM room ${i + 1}`])];
  return `<div style="border-top:1px solid var(--line);margin:6px 0 2px;padding-top:6px"><b>Panel rooms</b><div class="grid2" style="margin-top:4px"><label class="f">HM panel rooms${sel('lc_rpm', rp.mode, mo)}</label><label class="f">Main panel room${sel('lc_rpmain', +rp.main > k ? 'sep' : rp.main, mn)}</label></div><p class="note" style="margin:2px 0 0">The main panel room feeds each HM panel room by its own cable, round the ground in the trench; each HM panel room feeds the floodlights of its masts. ${rp.mode === 'each' ? 'Each room stands just outside its mast.' : `Each room serves the masts on its side (${k} groups) and stands outside the middle of them.`} Combined: the main panels stand in that HM panel room – no feeder run to it. Rooms dragged on the cable plan stay put until the choice here changes.</p></div>`; }
function lcRoomPlanBind() { const re = () => { try { renderLc(); } catch (e) { void e; } };
  $('#lc_rpm')?.addEventListener('change', (e) => { EL.roomPlan = { ...roomPlan(), mode: e.target.value }; if (+EL.roomPlan.main > rpCount(LC().masts.length, EL.roomPlan.mode)) EL.roomPlan.main = 'sep'; re(); });
  $('#lc_rpmain')?.addEventListener('change', (e) => { EL.roomPlan = { ...roomPlan(), main: e.target.value }; re(); }); }

// ================================================================ LIGHTING CALC – the other sports: football, rugby, athletics, tennis, pickleball, volleyball
// each sport: its ground (a rectangle with run-off, or a 400 m track), the two areas checked, the no-mast zone, standards, cameras and the mast / pole layout;
