  for (let i = 0; i < F.pb.k; i++) { const a = (2 * Math.PI * i) / F.pb.k; s += `<circle cx="${sx + rb * Math.cos(a)}" cy="${sy + rb * Math.sin(a)}" r="2.6" fill="${reb}"/>`; }
  s += T(sx + rr + 14, sy - 10, `${F.pb.k} H${F.pb.b} – mark 06 (${r1((100 * F.pb.a) / (F.q.Ab * 1e6), 2)} %)`, ink, 9.5) + T(sx + rr + 14, sy + 6, 'H10 helix @ 150 (@ 100 top 3 m) – 07', ink, 9.5) + T(sx + rr + 14, sy + 22, `H16 spacer rings @ 3 m – 08 · cover ${p.pcov}`, ink, 9.5);
