function pileBind(rerender) {
  const p = PL(), go = () => rerender(), bh = () => p.bh;
  document.querySelectorAll('[data-plwhy]').forEach((x) => x.addEventListener('change', () => { p.why = { ...(p.why ?? {}), [x.dataset.plwhy]: x.checked }; go(); }));
  $('#pl_maxB')?.addEventListener('change', (e) => { p.maxB = e.target.value === '' ? '' : Math.max(2, +e.target.value); go(); }); $('#pl_useBh')?.addEventListener('change', (e) => { p.useBh = e.target.checked; go(); });
  $('#pl_mode')?.addEventListener('click', (e) => { const b = e.target.closest('[data-plm]'); if (b) { p.mode = b.dataset.plm; if (p.mode === 'pile' && !p.bh) p.step = 1; go(); } });
  $('#pl_steps')?.addEventListener('click', (e) => { const b = e.target.closest('[data-pls]'); if (b) { p.step = +b.dataset.pls; go(); } });
  $('#pl_prev')?.addEventListener('click', () => { p.step = Math.max(1, p.step - 1); go(); }); $('#pl_next')?.addEventListener('click', () => { p.step = Math.min(5, p.step + 1); go(); });
  $('#pl_ex')?.addEventListener('click', () => { p.bh = BH_EX(); Object.assign(p, { qb: 2, fuR: 200, fos: 2, sock: 1, Ms: 4720, Mu: 5900, Ns: 182.4, Nu: 228, Hs: '', mode: 'auto' }); go(); });
  $('#pl_new')?.addEventListener('click', () => { p.bh = { name: 'BH-1', site: '', gwl: 2, rock: '', rockD: '', L: [{ t: 0, b: 1, k: 'fill', d: 'Surface layer', n: '', fu: '', qb: '' }] }; go(); });
  $('#pl_clr')?.addEventListener('click', () => { p.bh = { name: 'BH-1', site: '', gwl: 2, rock: '', rockD: '', L: [{ t: 0, b: 1, k: 'fill', d: 'Surface layer', n: '', fu: '', qb: '' }] }; go(); });
  $('#pl_add')?.addEventListener('click', () => { const L = bh().L, t = L.length ? +L[L.length - 1].b : 0; L.push({ t, b: Math.round((t + 1.5) * 100) / 100, k: 'sand', d: '', n: '', fu: '', qb: '' }); go(); });
  const fixTops = () => { const L = bh().L; L.forEach((l, i) => { if (i) l.t = +L[i - 1].b; }); };
  document.querySelectorAll('[data-pldel]').forEach((x) => x.addEventListener('click', () => { bh().L.splice(+x.dataset.pldel, 1); if (bh().L[0]) bh().L[0].t = 0; fixTops(); go(); }));
  const each = (attr, fn) => document.querySelectorAll(`[${attr}]`).forEach((x) => x.addEventListener('change', () => { fn(bh().L[+x.getAttribute(attr)], x.value); fixTops(); go(); }));
  each('data-plb', (l, v) => (l.b = Math.max(+l.t + 0.05, +v))); each('data-plk', (l, v) => (l.k = v)); each('data-pld', (l, v) => (l.d = v)); each('data-pln', (l, v) => (l.n = v === '' ? '' : +v)); each('data-plf', (l, v) => (l.fu = v === '' ? '' : Math.max(0, +v))); each('data-plq', (l, v) => (l.qb = v === '' ? '' : Math.max(0, +v)));
  const f = (id, fn) => { const i = $('#' + id); if (i) i.addEventListener('change', () => { fn(i.value); go(); }); };
  f('pl_name', (v) => (bh().name = v)); f('pl_site', (v) => (bh().site = v)); f('pl_gwl', (v) => (bh().gwl = Math.max(0, +v))); f('pl_rock', (v) => (bh().rock = v === '' ? '' : Math.max(0, +v))); f('pl_rockd', (v) => (bh().rockD = v));
  f('pl_qb', (v) => { if (v !== 'c') p.qb = +v; else p.qb = 2.5; }); f('pl_qbc', (v) => (p.qb = Math.max(0.1, +v))); f('pl_fuR', (v) => (p.fuR = Math.max(0, +v))); f('pl_fos', (v) => (p.fos = Math.max(1, +v))); f('pl_sock', (v) => (p.sock = Math.max(0, +v)));
  ['Ms', 'Mu', 'Ns', 'Nu', 'Hs'].forEach((k) => f('pl_' + k, (v) => (p[k] = v === '' ? '' : +v)));
  f('pl_D', (v) => (p.D = v === 'auto' ? 'auto' : +v)); f('pl_n', (v) => (p.n = v === 'auto' ? 'auto' : +v)); f('pl_s', (v) => (p.s = v === '' ? 'auto' : Math.max(1, +v))); f('pl_hc', (v) => (p.hc = v === '' ? 'auto' : Math.max(0.6, +v)));
  f('pl_fcu', (v) => (p.fcu = +v)); f('pl_fy', (v) => (p.fy = +v)); f('pl_cov', (v) => (p.cov = +v)); f('pl_pcov', (v) => (p.pcov = +v)); f('pl_rho', (v) => (p.rho = +v)); f('pl_meth', (v) => (p.meth = v));
  $('#pl_auto')?.addEventListener('click', () => { p.D = 'auto'; p.n = 'auto'; p.s = 'auto'; go(); });
  document.querySelectorAll('[data-plo]').forEach((x) => x.addEventListener('click', () => { const F0 = mastStruct()?.F, o = (F0?.kind === 'pile' ? F0 : F0?.rec?.pile)?.opts?.[+x.dataset.plo]; if (o) { p.D = o.D; p.n = o.n; p.s = o.s; if (F0?.kind !== 'pile') p.mode = 'pile'; go(); } }));
}

// =================== buildings – panel rooms, operations rooms and small structures: the requirement → architectural and structural drawing set, 3D, and cable trenches checked against the cable makers' data ===================
// x runs along the width W (west → east), y along the length L (north → south), z up from the ground; FFL = top of the plinth
const BG_KIND = { panel: { name: 'Panel room', ll: 5, h: 3.6, door: 'double' }, ops: { name: 'Operations / control room', ll: 3, h: 3.3, door: 'single' }, store: { name: 'Store / workshop', ll: 5, h: 3.6, door: 'roller' }, custom: { name: 'Other building', ll: 3, h: 3.3, door: 'single' } };
const BG_WALL = { brick225: { name: 'Brick 225 mm, plastered both sides', t: 0.225, kpa: 4.6 }, block200: { name: 'Cement block 200 mm, plastered', t: 0.2, kpa: 3.2 }, block150: { name: 'Cement block 150 mm, plastered', t: 0.15, kpa: 2.6 } };
const BG_ITEM = { door: 'Door', door2: 'Double door', roller: 'Roller shutter', window: 'Window', louvre: 'Louvre', glass: 'Glass façade', trench: 'Cable trench', panel: 'Panel' };
const BG_WALL_ITEMS = ['door', 'door2', 'roller', 'window', 'louvre', 'glass'];
// overall diameters (mm) and minimum bending radius (× OD) – typical makers' data for BS 6346 / BS 5467 / BS 7889 / IEC 60502-2 cables; type the maker's figure on a cable to override
const BG_CBL = {
  swa4: { name: '4-core Cu/PVC/SWA/PVC (BS 6346)', k: 6, od: { 1.5: 14, 2.5: 15.5, 4: 17.5, 6: 19, 10: 22, 16: 24.5, 25: 28.5, 35: 31, 50: 35, 70: 39.5, 95: 45, 120: 49, 150: 54, 185: 60, 240: 67, 300: 74, 400: 83 } },
  swa2: { name: '2-core Cu/PVC/SWA/PVC (BS 6346)', k: 6, od: { 1.5: 12.5, 2.5: 13.5, 4: 15, 6: 16, 10: 18, 16: 20, 25: 23, 35: 25.5, 50: 28.5 } },
  xswa4: { name: '4-core Cu/XLPE/SWA/PVC (BS 5467)', k: 8, od: { 1.5: 13.5, 2.5: 14.5, 4: 16.5, 6: 18, 10: 20.5, 16: 23, 25: 27, 35: 29.5, 50: 33, 70: 37.5, 95: 42.5, 120: 46.5, 150: 51, 185: 57, 240: 63.5, 300: 70, 400: 79 } },
  x1: { name: '1-core Cu/XLPE/PVC (BS 7889)', k: 8, od: { 50: 15, 70: 17, 95: 19, 120: 21, 150: 23, 185: 25.5, 240: 28.5, 300: 31.5, 400: 35.5, 500: 39.5, 630: 44 } },
  mv3: { name: '3-core 11 kV Cu/XLPE/SWA/PVC (IEC 60502-2)', k: 12, od: { 35: 52, 50: 55, 70: 59, 95: 63, 120: 67, 150: 71, 185: 75, 240: 81, 300: 87 } },
  ctl: { name: 'Control / instrumentation cable, armoured', k: 8, od: { 1: 12, 1.5: 13, 2.5: 14 } },
  fo: { name: 'Fibre optic, armoured', k: 20, od: { 1: 10 } },
};
