  const wrap = $('#lcWrap'); if (!wrap || $('#lcDim')) return; const bar = wrap.previousElementSibling?.classList.contains('zoombar') ? wrap.previousElementSibling : null;
  const seg = document.createElement('div'); seg.className = 'seg'; seg.id = 'lcDim'; seg.style.marginRight = 'auto'; seg.innerHTML = '<button data-lcdim="plan" aria-pressed="true">Plan</button><button data-lcdim="3d" aria-pressed="false">3D</button><button data-lcdim="real" aria-pressed="false">Realistic</button>';
  if (bar) bar.prepend(seg); else wrap.parentElement.insertBefore(seg, wrap);
  const box = document.createElement('div'); box.id = 'lc3dBox'; box.hidden = true;
  box.innerHTML = '<canvas id="lc3d"></canvas><div class="lc3Ctl"><div class="seg" id="lc3Views"><button data-lc3v="iso">Iso</button><button data-lc3v="front">Front</button><button data-lc3v="side">Side</button><button data-lc3v="top">Top</button><button data-lc3v="turn">Turn 90°</button><button data-lc3v="head" title="Each press: the next mast’s head frame">Mast head</button></div><label class="f chk"><input type="checkbox" id="lc3Beams" checked> beams</label><label class="f chk"><input type="checkbox" id="lc3Labels" checked> labels</label></div><div class="lc3Hint">Drag to turn · pinch or wheel to zoom · two fingers or Shift + drag to move</div>';
  wrap.appendChild(box);
  seg.addEventListener('click', (e) => { const b = e.target.closest('[data-lcdim]'); if (!b) return; lcRealSet(b.dataset.lcdim === 'real'); lc3Set(b.dataset.lcdim !== 'plan'); });
  $('#lc3Views').addEventListener('click', (e) => { const b = e.target.closest('[data-lc3v]'); if (!b) return; const v = b.dataset.lc3v;
    if (v === 'head') { const L = LC(), n = L.masts.length; if (!n) return; LC3.mi = (LC3.mi + 1) % n; const m = L.masts[LC3.mi], G = lcFrameGeom(m), az = lcMastAz(m); Object.assign(LC3, { px: m.x, py: m.y, pz: +m.h + (G.H ?? 1) / 2, dist: Math.max(0.04, (Math.max(G.W, G.H) * 3.5) / (Math.max(L.g.Rx, L.g.Ry) * 2.5 + 20)), yaw: Math.atan2(-Math.cos(az), -Math.sin(az)) + 0.4, pitch: 0.15 }); lc3Paint(); return; } // from the field side, a little off square
    Object.assign(LC3, { pz: null }, v === 'iso' ? { yaw: 0.55, pitch: 0.5, dist: 1, px: 0, py: 0 } : v === 'front' ? { yaw: 0, pitch: 0.18, dist: 1, px: 0, py: 0 } : v === 'side' ? { yaw: Math.PI / 2, pitch: 0.18, dist: 1, px: 0, py: 0 } : v === 'top' ? { yaw: 0, pitch: 1.5, dist: 1, px: 0, py: 0 } : { yaw: LC3.yaw + Math.PI / 2 }); lc3Paint(); });
  $('#lc3Beams').addEventListener('change', (e) => { LC3.beams = e.target.checked; lc3Paint(); });
  $('#lc3Labels').addEventListener('change', (e) => { LC3.labels = e.target.checked; lc3Paint(); });
  const cvs = $('#lc3d'), pts = new Map(); let base = null;
  const snap = (e) => ({ yaw: LC3.yaw, pitch: LC3.pitch, dist: LC3.dist, px: LC3.px, py: LC3.py, pan: !!(e?.shiftKey || e?.button === 1 || e?.button === 2), p: new Map(pts) });
  cvs.addEventListener('pointerdown', (e) => { cvs.setPointerCapture?.(e.pointerId); pts.set(e.pointerId, [e.clientX, e.clientY]); base = snap(e); e.preventDefault(); });
  cvs.addEventListener('pointermove', (e) => { if (!pts.has(e.pointerId) || !base) return; pts.set(e.pointerId, [e.clientX, e.clientY]); const L = LC(), k = (Math.max(L.g.Rx, L.g.Ry) * 2.5 * LC3.dist) / Math.max(300, cvs.clientWidth);
    const pan = (dx, dy) => { const c = Math.cos(LC3.yaw), s = Math.sin(LC3.yaw); LC3.px = base.px + (-dx * c + dy * s) * k; LC3.py = base.py + (dx * s + dy * c) * k; };
    if (pts.size === 1) { const [a] = [...base.p.values()], [b] = [...pts.values()]; if (base.pan) pan(b[0] - a[0], b[1] - a[1]); else { LC3.yaw = base.yaw + (b[0] - a[0]) * 0.008; LC3.pitch = Math.max(0.06, Math.min(1.52, base.pitch + (b[1] - a[1]) * 0.006)); } }
    else if (pts.size >= 2 && base.p.size >= 2) { const q = [...pts.values()], q0 = [...base.p.values()], d1 = Math.hypot(q[0][0] - q[1][0], q[0][1] - q[1][1]), d0 = Math.hypot(q0[0][0] - q0[1][0], q0[0][1] - q0[1][1]) || 1; LC3.dist = Math.max(0.15, Math.min(4, base.dist * (d0 / (d1 || 1)))); pan((q[0][0] + q[1][0] - q0[0][0] - q0[1][0]) / 2, (q[0][1] + q[1][1] - q0[0][1] - q0[1][1]) / 2); }
    lc3Paint(); });
  const up = (e) => { pts.delete(e.pointerId); base = snap(); };
  cvs.addEventListener('pointerup', up); cvs.addEventListener('pointercancel', up); cvs.addEventListener('contextmenu', (e) => e.preventDefault());
  cvs.addEventListener('wheel', (e) => { e.preventDefault(); LC3.dist = Math.max(0.15, Math.min(4, LC3.dist * (e.deltaY > 0 ? 1.1 : 1 / 1.1))); lc3Paint(); }, { passive: false });
  box.addEventListener('touchstart', (e) => e.stopPropagation(), { passive: true });
  if (window.ResizeObserver) new ResizeObserver(() => { if (LC3D) lc3Paint(); }).observe(wrap);
}
function lc3Set(on) {
  LC3D = !!on; if (!LC3D && LCREAL) lcRealSet(false); const wrap = $('#lcWrap'); if (!wrap) return; wrap.classList.toggle('lc3on', LC3D); $('#lc3dBox').hidden = !LC3D;
  document.querySelectorAll('#lcDim [data-lcdim]').forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.lcdim === (LC3D ? (LCREAL ? 'real' : '3d') : 'plan'))));
  const bar = $('#lcDim')?.parentElement; if (bar?.classList.contains('zoombar')) [...bar.children].forEach((c) => { if (c.id !== 'lcDim') c.style.visibility = LC3D ? 'hidden' : ''; });
  if (LC3D) { wrap.scrollTop = 0; wrap.scrollLeft = 0; lc3Paint(); }
}
function lc3Sync() { lc3Init(); if (LC3D) lc3Paint(); }

// =================== High masts from the Light calc: one design per mast type (height to the head frame, floodlights, frame size, fixture weight and windage) with its foundation; anything changed in Poles & masts is kept for that type ===================
const LCM_M0 = JSON.parse(JSON.stringify({ ...ST.mast, fwa: ST.mast.fwa ?? 0.28, fH: 0 }));
const LCM_KEYS = ['h', 'n', 'fw', 'fwa', 'tilt', 'frame', 'fshape', 'fr', 'fa', 'fb', 'fH', 'frW', 'frA', 'ftilt', 'fpat', 'fcols', 'frows', 'fdx', 'fdy'];
const lcId = (id) => document.getElementById(id);
let LCHM_MEMO = null, LCHMOPEN = false;
// the maker's figures when entered, else an estimate from the wattage (LED floodlights ≈ 8 kg + 13 g/W, ≈ 0.08 m² + 0.14 m²/kW)
const lcLumKg = (pm) => (+pm?.kg > 0 ? +pm.kg : Math.round(8 + (pm?.W || 1000) * 0.013));
const lcLumWa = (pm) => (+pm?.wa > 0 ? +pm.wa : Math.round((0.08 + (pm?.W || 1000) * 0.00014) * 100) / 100);
const lcLumEst = (pm) => !(+pm?.kg > 0 && +pm?.wa > 0);
function lcHmBase(L, m, mi, Q) {
  const G = lcFrameGeom(m), q = Q.filter((x) => x.mi === mi), pms = m.lights.map((l) => L.lums[l.lum || m.lum || L.lum]).filter(Boolean), k = Math.max(1, pms.length), ring = G.t === 'ring', A = (ring ? 4 * G.r : G.W * G.H) * ({ trap: 0.8, arc: 1.1, vee: 1.1, stepped: 1.15 }[G.t] ?? 1);
  return { h: +m.h, n: m.lights.length, fw: Math.round((pms.reduce((t, pm) => t + lcLumKg(pm), 0) / k) * 10) / 10, fwa: Math.round((pms.reduce((t, pm) => t + lcLumWa(pm), 0) / k) * 100) / 100,
    tilt: q.length ? Math.round(q.reduce((t, x) => t + Math.max(0, 90 - x.tilt), 0) / q.length / 5) * 5 : 20, frame: ring ? 'sym' : 'asym', fshape: ring ? 'ring' : 'rect', fr: ring ? G.r : 1.2, fa: ring ? 2.4 : Math.round((0.3 + G.D) * 10) / 10, fb: ring ? 1.6 : G.W, fH: G.H,
    frW: Math.round((150 + 35 * A) / 10) * 10, frA: Math.round((0.6 + 0.12 * A) * 10) / 10, ftilt: +m.frame?.tilt || 0, fpat: G.t, fcols: G.cols, frows: G.rows, fdx: G.dx, fdy: G.dy };
}
const lcHmFrameTxt = (b) => `${(LC_FRAMES[b.fpat] ?? 'frame').split(' – ')[0].toLowerCase()} ${b.fshape === 'ring' ? `ring r ${b.fr} m` : `${b.fb} × ${b.fH} m`}`;
// masts with the same height, floodlights, frame and fixtures share one design
function lcHmTypes(L) {
  const Q = lcLums(L), T = [];
  L.masts.forEach((m, mi) => { const b = lcHmBase(L, m, mi, Q), k = JSON.stringify({ ...b, tilt: 0 }), t = T.find((x) => x.k === k); if (t) { t.names.push(m.name); t.b.tilt = Math.min(t.b.tilt, b.tilt); } else T.push({ k, b, names: [m.name] }); }); // the floodlights' tilt does not split a type – the flattest (most windage) governs
  return T.sort((a, c) => c.b.h * c.b.n - a.b.h * a.b.n || c.b.h - a.b.h);
}
function stLcmCapture() {
  const lm = ST.lcm, t = lm?.types?.[lm.cur]; if (!t || lm.cur == null) return; const ref = { ...LCM_M0, ...t.b }, o = {};
  Object.keys(ST.mast).forEach((k) => { if (JSON.stringify(ST.mast[k]) !== JSON.stringify(ref[k])) o[k] = ST.mast[k]; }); t.o = o;
}
// the Light calc's masts into Poles & masts: Light calc values win where they changed, the other settings made there are kept
function lcHmSync(L) {
  if (!L.masts.length) return []; stLcmCapture();
  const T = lcHmTypes(L), first = !ST.lcm, old = ST.lcm?.types ?? [], selN = old[ST.lcm?.sel ?? 0]?.names ?? [];
  const types = T.map((t) => { const p = old.find((x) => x.names.some((n) => t.names.includes(n))), o = { ...(p?.o ?? {}) }; if (p) LCM_KEYS.forEach((k) => { if (k in o && JSON.stringify(p.b[k]) !== JSON.stringify(t.b[k])) delete o[k]; }); return { names: t.names, b: t.b, o }; });
  const same = ST.lcm && JSON.stringify(old.map((x) => [x.names, x.b, x.o])) === JSON.stringify(types.map((x) => [x.names, x.b, x.o]));
  if (same) return ST.lcm.types;
  ST.lcm = { types, sel: Math.max(0, types.findIndex((x) => x.names.some((n) => selN.includes(n)))), cur: null }; if (first) ST.type = 'mast';
  return types;
}
function stLcmEnter() {
  const lm = ST.lcm; if (!lm?.types?.length || !stIsMast()) return; if (lm.sel >= lm.types.length) lm.sel = 0;
  if (lm.cur === lm.sel) { stLcmCapture(); return; } stLcmCapture(); const t = lm.types[lm.sel]; ST.mast = { ...LCM_M0, ...t.b, ...t.o }; lm.cur = lm.sel;
}
function lcHmSum(S) {
  const { P, BT, F, checks } = S, g = P.g, bad = checks.filter((c) => !c.ok && !c.soft), secT = Array.from({ length: g.nSec }, (_, i) => Math.round(g.tOf(i * g.sl + 0.01) * 1000));
  const fd = F.kind === 'pile' ? (F.fail ? 'piles – none fits the borehole' : `${F.n} piles Ø ${F.D} m to ${r1(F.z, 1)} m · cap ${r1(F.B, 2)} m sq × ${r1(F.hc, 2)} m`) : F.need === 'borehole' ? 'piles – enter the borehole log in Poles & masts' : F.fail ? 'pad – none fits; try piles' : `pad ${r1(F.B, 2)} m sq × ${r1(F.tpad, 2)} m at ${r1(F.Df, 2)} m`;
  return { D: Math.round(P.D * 1000), Dt: Math.round(g.Dt * 1000), secT, gr: P.gr, nSec: g.nSec, kg: Math.round(P.A.mass), bolts: BT ? `${BT.n} × M${BT.d} ${BT.grade}, PCD ${Math.round(BT.PCD * 1000)}, plate ${BT.tp} mm` : '', fd, kind: F.kind, ok: P.ok && !bad.length && !F.fail && F.need !== 'borehole', bad: bad.map((c) => c.t) };
}
function lcHmDesign() {
  const T = ST.lcm?.types ?? []; if (!T.length) return []; stLcmCapture();
  const { lcm, mast, ...rest } = ST, key = JSON.stringify([T.map((t) => [t.b, t.o]), rest]); void lcm; void mast;
  if (LCHM_MEMO?.key === key) return LCHM_MEMO.v;
  const keep = ST.mast, v = T.map((t) => { ST.mast = { ...LCM_M0, ...t.b, ...t.o }; try { const S = mastStruct(); return S ? lcHmSum(S) : { err: 'the mast could not be designed – check the inputs in Poles & masts' }; } catch (e) { return { err: e.message || String(e) }; } finally { ST.mast = keep; } });
  LCHM_MEMO = { key, v }; return v;
}
const LCHM_FOUND = [['auto', 'Recommend'], ['pad', 'Pad'], ['pile', 'Piles']];
// the narrow Poles & masts pane: one short card per type
function lcHmCards(open) {
  const T = ST.lcm?.types ?? [], D = lcHmDesign();
  return `<div style="display:grid;gap:6px;margin-top:6px">${T.map((t, i) => { const d = D[i] ?? {}, b = { ...t.b, ...t.o };
    return `<div style="border:1px solid var(--line);border-radius:8px;padding:6px 8px;font-size:12px;line-height:1.45${ST.lcm.sel === i && !open ? ';background:rgba(42,111,219,.08);border-color:#2a6fdb' : ''}"><b>${d.ok ? '✓' : '⚠'} ${esc(t.names.join(', '))}</b><br>${b.h} m · ${b.n} × ${b.fw} kg, ${b.fwa} m² · frame ${lcHmFrameTxt(b)}<br>${d.err ? `<span style="color:var(--bad)">${esc(d.err)}</span>` : `Shaft Ø ${d.D} → ${d.Dt} mm, ${d.gr}, ${d.nSec} sections ${d.secT.join('/')} mm, ${d.kg} kg<br>Bolts ${esc(d.bolts)}<br><span${d.ok ? '' : ' style="color:var(--bad)"'}>Foundation: ${esc(d.fd)}${d.bad?.length ? ` – fails: ${esc(d.bad.join(', '))}` : ''}</span>`}${open ? `<br><button class="btn" data-lchmo="${i}" style="margin-top:4px">Open in Poles &amp; masts</button>` : ''}</div>`; }).join('')}</div>`;
}
// the Light calc pane: frame size for all masts, the fixtures' weight and windage, the foundation choice and the designs
function lcHmHtml(L) {
  if (!L.masts.length) return ''; const used = [...new Set(L.masts.flatMap((m) => m.lights.map((l) => l.lum || m.lum || L.lum)))].filter((id) => L.lums[id]), p = ST.pile ?? PILE_DEF, w = L.masts.map((m) => +m.frame?.w || 0), wAll = w.every((x) => x === w[0]) ? w[0] || '' : '';
  return `<details id="lc_hmdet"${LCHMOPEN ? ' open' : ''}><summary><b>High masts &amp; foundations</b></summary>
    <p class="note" style="margin:0 0 4px">Mast height is to the bottom of the head frame; the floodlight rows stack above it. A set frame width gives the floodlights per row and the rows follow – a frame more than 1.2 × taller than wide is widened, with the rows kept near full. Blank: about 1.3 × as wide as tall.</p>
    <label class="f">Head frame shape – all masts<select id="lc_fpat">${(() => { const ts = L.masts.map((m) => m.frame?.t ?? 'grid'), one = ts.every((x) => x === ts[0]) ? ts[0] : ''; return (one ? '' : '<option value="" selected>Mixed – as set per mast</option>') + Object.entries(LC_FRAMES).map(([k, t]) => `<option value="${k}"${k === one ? ' selected' : ''}>${esc(t)}</option>`).join(''); })()}</select></label>
    <div class="grid2"><label class="f">Head frame tilt – all masts °<input type="number" id="lc_ftilt" min="0" max="30" step="1" placeholder="0" value="${(() => { const t = L.masts.map((m) => +m.frame?.tilt || 0); return t.every((x) => x === t[0]) ? t[0] || '' : ''; })()}"></label><span class="note" style="align-self:end">The frame leans its top towards the field – the floodlights move with it; the mast takes the eccentricity.</span></div>
    <div class="grid2"><label class="f">Head frame width – all masts m<input type="number" id="lc_fw" min="0.8" step="0.1" placeholder="per mast" value="${wAll}"></label><label class="f">Gap between floodlights / rows m<input type="text" id="lc_fgap" value="${L.masts[0]?.frame?.dx ?? 0.8} / ${L.masts[0]?.frame?.dy ?? 0.9}" placeholder="0.8 / 0.9"></label></div>
    <div class="tablewrap"><table class="sch"><thead><tr><th>Floodlight</th><th>Weight kg</th><th>Windage m²</th></tr></thead><tbody>${used.map((id) => { const pm = L.lums[id]; return `<tr><td>${esc(pm.name)}${lcLumEst(pm) ? '<br><small style="color:#b45309">estimated – enter the datasheet values</small>' : ''}</td><td><input type="number" data-lckg="${esc(id)}" min="1" step="0.5" value="${+pm.kg > 0 ? pm.kg : ''}" placeholder="${lcLumKg(pm)}" style="width:70px"></td><td><input type="number" data-lcwa="${esc(id)}" min="0.02" step="0.01" value="${+pm.wa > 0 ? pm.wa : ''}" placeholder="${lcLumWa(pm)}" style="width:70px"></td></tr>`; }).join('')}</tbody></table></div>
    <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:6px 0"><span>Foundation</span><div class="seg" id="lc_hmf">${LCHM_FOUND.map(([k, t]) => `<button data-lchmf="${k}" aria-pressed="${(p.mode ?? 'auto') === k}">${k === 'pile' ? 'Design with piles' : t}</button>`).join('')}</div></div>
    ${p.mode === 'pile' && !bhOk() ? '<p class="note" style="margin:0 0 4px;color:#b45309">Piles need the borehole log: open a mast in Poles &amp; masts → Foundation, type the log (or load the example). Pile size, number, spacing and loads can be entered there by hand.</p>' : ''}
    ${lcHmCards(true)}
    <p class="note" style="margin:4px 0 0">Designed automatically from the masts above (shaft, flange, bolts, foundation – wind and soil as set in Poles &amp; masts). Open a type to change anything; those changes are kept when the Light calc changes, unless the Light calc changes the same value.</p></details>`;
}
function lcHmBind(L) {
  lcId('lc_hmdet')?.addEventListener('toggle', (e) => (LCHMOPEN = e.target.open));
  const go = (msg) => { lcInvalidate(); lcHmSync(L); renderLc(); if (msg) LCMSG = msg; };
  lcId('lc_fpat')?.addEventListener('change', (e) => { const v = e.target.value; if (!v) return; lcSnap(L, 'head frame shape'); L.masts.forEach((m) => { m.frame = { ...(m.frame ?? { dx: 0.8, dy: 0.9 }), t: v }; if (v === 'ring' && !m.frame.r) m.frame.r = 1.5; }); go(); });
  lcId('lc_ftilt')?.addEventListener('change', (e) => { lcSnap(L, 'head frame tilt'); const v = Math.max(0, Math.min(30, +e.target.value || 0)); L.masts.forEach((m) => { m.frame = { ...(m.frame ?? { t: 'grid', dx: 0.8, dy: 0.9 }) }; if (v) m.frame.tilt = v; else delete m.frame.tilt; }); go(); });
  lcId('lc_fw')?.addEventListener('change', (e) => { lcSnap(L, 'head frame width'); const v = +e.target.value; L.masts.forEach((m) => { if (m.frame?.t === 'ring') return; m.frame = { ...(m.frame ?? { t: 'grid', dx: 0.8, dy: 0.9 }) }; if (v > 0) m.frame.w = v; else delete m.frame.w; }); go(); });
  lcId('lc_fgap')?.addEventListener('change', (e) => { const [a, b] = String(e.target.value).split('/').map((x) => +x); if (!(a >= 0.3)) return; lcSnap(L, 'frame gaps'); L.masts.forEach((m) => { if (m.frame?.t === 'ring') return; m.frame = { ...(m.frame ?? { t: 'grid' }), dx: a, ...(b >= 0.3 ? { dy: b } : {}) }; }); go(); });
  document.querySelectorAll('[data-lckg]').forEach((x) => x.addEventListener('change', () => { const pm = L.lums[x.dataset.lckg]; if (pm) { pm.kg = +x.value > 0 ? +x.value : undefined; go(); } }));
  document.querySelectorAll('[data-lcwa]').forEach((x) => x.addEventListener('change', () => { const pm = L.lums[x.dataset.lcwa]; if (pm) { pm.wa = +x.value > 0 ? +x.value : undefined; go(); } }));
  lcId('lc_hmf')?.addEventListener('click', (e) => { const b = e.target.closest('[data-lchmf]'); if (!b) return; PL().mode = b.dataset.lchmf; LCHM_MEMO = null; renderLc(); });
  document.querySelectorAll('[data-lchmo]').forEach((x) => x.addEventListener('click', () => { lcHmSync(L); stLcmCapture(); ST.lcm.sel = +x.dataset.lchmo; if (!stIsMast()) ST.type = 'mast'; setTab('str'); }));
}
// Poles & masts: which Light calc mast type is on the page, and all of them at a glance
function stLcmHtml() {
  const lm = ST.lcm; if (!lm?.types?.length) return ''; const t = lm.types[lm.sel] ?? lm.types[0];
  return `<div style="border:1.5px solid var(--ink);border-radius:10px;padding:8px 10px;margin-bottom:8px"><b>High masts from the Light calc</b>
    <label class="f">Mast type on this page<select id="st_lcm">${lm.types.map((x, i) => `<option value="${i}"${i === lm.sel ? ' selected' : ''}>${esc(x.names.join(', '))} – ${x.b.h} m, ${x.b.n} floodlights</option>`).join('')}</select></label>
    ${!stIsMast() ? '<button class="btn" id="st_lcmgo">Show the high masts</button>' : Object.keys(t.o).length ? `<p class="note" style="margin:2px 0">Changed here: ${esc(Object.keys(t.o).join(', '))} <button class="btn" id="st_lcmreset">Back to the Light calc values</button></p>` : '<p class="note" style="margin:2px 0">Height, floodlights, head frame and fixture weight / windage come from the Light calc – change anything below; it is kept for this mast type.</p>'}
    ${lcHmCards()}</div>`;
}
function stLcmBind() {
  lcId('st_lcm')?.addEventListener('change', (e) => { stLcmCapture(); ST.lcm.sel = +e.target.value; if (!stIsMast()) ST.type = 'mast'; renderStruct(); });
  lcId('st_lcmgo')?.addEventListener('click', () => { if (!stIsMast()) ST.type = 'mast'; renderStruct(); });
  lcId('st_lcmreset')?.addEventListener('click', () => { const t = ST.lcm.types[ST.lcm.sel]; t.o = {}; ST.lcm.cur = null; renderStruct(); });
}

// =================== Poles & masts 3D – the mast as designed, set in the ground: superstructure (shaft, head frame, floodlights), substructure (base plate, bolts, pad or pile cap), piles and the soil layers; the part in focus full, the rest faded ===================
let ST3D = false, ST3RAF = 0, ST3M = null;
