function lcZCamRedef(L, G) { const D = Object.fromEntries(lcZCamDefs(G).map((s) => [s[0], s])); L.cams.filter((c) => c.gid === G.gid && !c.moved).forEach((c) => { const s = c.sk === 'fin' ? [0, 0, 0, ...lcZFinLocal(G), c.z] : D[c.k]; if (!s) return; c.lx = s[3]; c.ly = s[4]; c.def = { lx: s[3], ly: s[4], z: s[5] }; }); lcZCamSync(L, G.gid); }
const lcZPut0 = lcZPut;
lcZPut = function (L, G) { lcZPut0(L, G); lcZCamRedef(L, G); };
const lcZAdd0 = lcZAdd;
lcZAdd = function (L, sp) { const G = lcZAdd0(L, sp); if (sp !== 'extra') { lcZCamsAdd(L, G); lcZCentre(L); } return G; };
function lcZCamOn(L, G) { const on = lcZHasEc(L, G.gid); L.cams.filter((c) => c.gid === G.gid && !c.only).forEach((c) => (c.on = G.sport === 'cricket' ? on : on && c.main)); }
// does a camera count for an area – its own sport only, or the areas it is set for
function lcCamAp(L, c, a) { if (!c) return true; if (c.only) return c.only.includes(a); if (c.gid && L.sport === 'multi') { const z = (L.zones ?? []).find((q) => q.id === a); return !z || z.gid === c.gid; } return true; }
// moved away from the standard / usual position: flagged, with the way back
function lcCamDef(L, c) { if (!c.def) return null; if (c.lx == null) return { x: c.def.x, y: c.def.y, z: c.def.z }; const G = lcZGroups(L).find((q) => q.gid === c.gid); if (!G) return null; const cs = Math.cos((G.rot * Math.PI) / 180), sn = Math.sin((G.rot * Math.PI) / 180); return { x: Math.round((G.x + c.def.lx * cs - c.def.ly * sn) * 10) / 10, y: Math.round((G.y + c.def.lx * sn + c.def.ly * cs) * 10) / 10, z: c.def.z }; }
function lcCamMoved(L, c) {
  if (!c) return; if (c.gid && c.lx != null) { const G = lcZGroups(L).find((q) => q.gid === c.gid); if (G) { const cs = Math.cos((G.rot * Math.PI) / 180), sn = Math.sin((G.rot * Math.PI) / 180), dx = c.x - G.x, dy = c.y - G.y; c.lx = Math.round((dx * cs + dy * sn) * 10) / 10; c.ly = Math.round((-dx * sn + dy * cs) * 10) / 10; } }
  const D = lcCamDef(L, c); if (!D) return; const off = Math.hypot(c.x - D.x, c.y - D.y), dz = (+c.z || 0) - D.z; c.moved = off > 0.4 || Math.abs(dz) > 0.1;
  LCMSG = c.moved ? `⚠ Camera ${c.n} moved away from its standard / best-practice position (${c.src ?? 'the usual position'}): now ${Math.round(off * 10) / 10} m from it${Math.abs(dz) > 0.1 ? `, ${c.z} m high instead of ${D.z} m` : ''}. The camera checks use the new position – confirm it with the broadcaster; “Put it back” restores it.` : `Camera ${c.n} is at its standard position.`; }
function lcDetKey(d) { return (d.querySelector(':scope > summary b')?.textContent || d.querySelector(':scope > summary')?.textContent || '').trim().replace(/\s*C\d+$|\s*\d+$/, ''); } // sections keep their open / closed state across redraws
function lcDetState(el) { const m = new Map(); el.querySelectorAll('details').forEach((d) => { const k = lcDetKey(d); if (k) m.set(k, d.open); }); return m; }
function lcDetRestore(el, m) { el.querySelectorAll('details:not([id=lcSelBox])').forEach((d) => { const k = lcDetKey(d); if (m.has(k)) d.open = m.get(k); }); }
function lcSelShow() { const b = document.getElementById('lcSelBox'); if (!b) return; b.style.scrollMarginTop = ((document.querySelector('#lcInsp .lcTools')?.offsetHeight || 0) + 12) + 'px'; b.scrollIntoView({ behavior: 'smooth', block: 'start' }); b.style.outline = '2px solid #c8102e'; b.style.borderRadius = '8px'; setTimeout(() => { b.style.outline = ''; }, 1400); }
function lcCamNote(L, c) { const D = lcCamDef(L, c); if (!D) return ''; return `<div style="border:1.5px solid ${c.moved ? '#c8102e' : 'var(--line)'};border-radius:8px;padding:6px 8px;margin:4px 0;display:grid;gap:4px"><span class="note" style="margin:0">${c.moved ? '<b style="color:var(--bad)">⚠ Moved from the standard / best-practice position.</b> ' : ''}Standard position ${D.x} / ${D.y} m, ${D.z} m high – ${esc(c.src ?? '')}. ${c.gid && L.sport === 'multi' ? 'Checked on its own sport only. ' : ''}${LC_CAMNOTE}</span>${c.moved ? '<button class="btn" id="lcc_back">Put it back to the standard position</button>' : ''}</div>`; }
const lcBind1 = lcBind;
lcBind = function (L) { lcBind1(L); document.getElementById('lcc_back')?.addEventListener('click', () => { const c = L.cams[LCSEL?.i]; const D = c && lcCamDef(L, c); if (!D) return; lcSnap(L, `camera ${c.n} back to its position`); c.x = D.x; c.y = D.y; c.z = D.z; if (c.lx != null) { c.lx = c.def.lx; c.ly = c.def.ly; } c.moved = false; LCMSG = `Camera ${c.n} is back at its standard position.`; lcInvalidate(); renderLc(); }); };
// ---- the size of a sport or area: typed in, checked against the standard size; outlines marked by hand are replaced only after a warning
let LCZSIZE = null; // { gid, dim } – a size waiting for the warning to be answered
const LC_ZDIMN = { L: 'length', W: 'width', ex: 'run-off at the ends', ey: 'run-off at the sides', sl: 'straight length', r: 'inner kerb radius', lanes: 'lanes', lw: 'lane width', Rx: 'boundary half-length', Ry: 'boundary half-width' };
function lcZDev(G) { if (G.sport === 'extra') return ''; const s = lcZDims(G.sport), d = G.dim ?? {}; return Object.keys(s).filter((k) => LC_ZDIMN[k] && d[k] != null && s[k] != null && Math.abs(d[k] - s[k]) > 0.005).map((k) => `${LC_ZDIMN[k]} ${d[k]} m (standard ${s[k]} m)`.replace(/lanes (\d+) m \(standard (\d+) m\)/, 'lanes $1 (standard $2)')).join(', '); }
function lcZDimHtml(G) {
  const d = { ...lcZDims(G.sport), ...(G.dim ?? {}) }, num = (lab, k, a) => `<label class="f">${lab}<input type="number" data-zgd="${G.gid}" data-k="${k}" value="${d[k] ?? ''}" ${a}></label>`, g2 = (...x) => `<div class="grid2">${x.join('')}</div>`;
  const h = G.sport === 'athletics' ? g2(num('Straight length m', 'sl', 'min="40" step="0.01"'), num('Inner kerb radius m (infield)', 'r', 'min="20" step="0.01"')) + g2(num('Lanes', 'lanes', 'min="4" max="10" step="1"'), num('Lane width m', 'lw', 'min="1" max="1.3" step="0.01"'))
    : G.sport === 'cricket' ? g2(num('Boundary half-length m', 'Rx', 'min="40" step="1"'), num('Boundary half-width m', 'Ry', 'min="40" step="1"'))
    : G.sport === 'extra' ? g2(num('Length m (placed rectangle)', 'L', 'min="2" step="1"'), num('Width m', 'W', 'min="2" step="1"'))
    : g2(num('Length m', 'L', 'min="5" step="0.5"'), num('Width m', 'W', 'min="3" step="0.5"')) + g2(num('Run-off at the ends m', 'ex', 'min="0" step="0.5"'), num('Run-off at the sides m', 'ey', 'min="0" step="0.5"'));
  const dv = lcZDev(G); return h + (dv ? `<span class="note" style="margin:0;color:var(--bad)">⚠ Not the standard size – ${esc(dv)}.</span>` : '');
}
function lcZSizeWarn(G) { return LCZSIZE?.gid === G.gid ? `<div style="border:1.5px solid #b45309;border-radius:8px;padding:8px;display:grid;gap:6px"><b>⚠ Resize ${esc(G.name)}?</b><span class="note" style="margin:0">Its outlines were marked by hand or edited. Resizing replaces them with the standard shape at the new size (run-off, special areas and its cameras follow). Undo brings them back.</span><div style="display:flex;gap:6px"><button class="btn" data-zszok="${G.gid}" style="background:var(--ink);color:var(--bg)">Resize anyway</button><button class="btn" data-zszx="1">Cancel</button></div></div>` : ''; }
function lcZResize(L, G, dim) { lcSnap(L, `size of ${G.name}`); G.dim = dim; lcZones(L).filter((z) => z.gid === G.gid).forEach((z) => { delete z.own; delete z.ed; }); lcZPut(L, G); const dv = lcZDev(G); LCMSG = dv ? `⚠ ${G.name} resized – not the standard size: ${dv}. The results use the new size; check it against the rules of the sport and the drawing.` : `${G.name} resized – the standard size.`; }

Object.assign(HELP, {'lc_std': 'The specification the design is checked against. Each one fills the targets for the three areas; change any value for the project, or pick Custom and name the client’s specification.', 'lcg_Rx': 'Cricket boundary, measured from the centre of the pitch along the pitch (59–82 m for international grounds).', 'lcg_Ry': 'Boundary measured across the pitch. Equal to the half-length for a round ground.', 'lcg_wA': 'Half-length of the wicket area (the ellipse round the pitch) – the zone that needs the highest and most even light.', 'lcg_wB': 'Half-width of the wicket area.', 'lcg_inR': 'The 30-yard (27.43 m) circle: two half-circles round the middle stumps joined by straight lines – the inner field.', 'lcg_fz': 'No mast may stand in line with the pitch behind the wickets – the batsman and bowler would look into the lights. The zone opens at ± this angle from the edges of the wicket area, so it covers any pitch laid in it.', 'lcg_clr': 'Masts must stand outside the playing area – this much beyond the boundary rope, for the boundary run-off, advertising boards and the sight screens.', 'lc_rule': 'Block: a mast cannot be dragged into the forbidden zone or the playing area, and an aim point cannot go steeper than 70° – it stops at the last allowed place. Allow: the move is made and the mast is marked ⚠ with the warning.', 'lc_link': 'Ticked: the masts here are the stadium layout’s from Cable distribution – positions, heights and floodlights come across whenever the layout changes there. Untick to move masts freely here.', 'lcg_wShape': 'The wicket area round the pitch, where the highest and most even light is needed. A rectangle (or a square with equal sizes) is the usual calculation area; the ellipse follows the LiDAC sketch.', 'lc_mf': 'Maintenance factor: the share of the new light left at the end of the maintenance period (LED ageing, dirt on the glass). Every result is maintained = initial × MF. LED floodlights: 0.8 is usual; 0.7–0.75 on dusty sites.', 'lc_pn': 'Number of masts for the automatic placement – at least 6 (LiDAC). The search tries the end masts at several angles from the pitch axis and several distances beyond the boundary, aims each layout and keeps the one closest to the targets.', 'lc_s': 'Per area (default): each area is calculated on its own grid like Relux – points at the cell centres, spacing 0.2 × 5^log d (EN 12464), so the figures match a Relux calculation; this spacing is then only for the colour map. One grid: every figure from one even grid at this spacing. The wicket area always uses a finer grid (≤ 1.5 m).', 'lc_gridm': 'EN 12193 / EN 12464: each calculation area its own grid – spacing 0.2 × 5^log10(d) with d the longer side, the long side the next odd number of points, the short side in proportion rounded up; points at the cell centres. This is Relux’s automatic raster (21 × 15 on a 104 × 70 m pitch). 5 × 5 m: the federation / broadcast grid (FIFA, UEFA, ICC – check the event’s regulations). Points per area: enter the grid of a specification or of an existing Relux / DIALux study. One grid: the older even grid at the spacing below. Before a Relux export a pop-up shows the grid to set in Relux.', 'lc_hc': 'Height of the vertical calculation points for the cameras – 1.5 m in the specification (the height of the players and the ball).', 'lc_plane': 'Vertical: the plane stands upright and faces the camera (EN 12193 practice). Square to the camera: tilted to face a high camera.', 'lcm_h': 'Height of the luminaires (the head frame) above the field. The suggestion meets 25° from the centre of the pitch and keeps aiming within 70° of vertical.', 'lcm_lock': 'Locked: the aim points stay where they are on the field when you drag the mast. Moves with the mast: the aiming travels with it. Re-aim: aimed again automatically after the move.', 'lcm_ft': 'How the luminaires sit on the head frame: rows × columns on a flat frame, rows stepped back, or round a ring.', 'lcm_fdx': 'Centre-to-centre gap between luminaires in a row – at least the luminaire width plus room for aiming.', 'lcm_fdy': 'Vertical gap between the rows of luminaires.', 'lcm_n': 'Number of floodlights on this mast. More keep the aiming: new ones copy the existing aim points.', 'lc_allh': 'Sets every mast to this height. Blank when the masts differ. The aim points stay where they are.', 'lc_alln': 'Sets the number of floodlights on every mast. The aiming is kept – new floodlights copy the existing aim points; optimise after.', 'lcm_az': 'Direction the head frame faces, in degrees (0 = along +x). Blank: it faces the centre of the pitch.', 'lcc_z': 'Height of the camera lens above the field.'});

