  const sv = $('#ispSvg'); if (sv) { sv.setAttribute('viewBox', P.vb); sv.innerHTML = P.s; }
  const sec = ispSecSvg(I, R), all = R.out.every((o) => o.pass), lightBad = R.out.filter((o) => o.ch.some((x) => !x.ok && !x.soft && x.light)).length;
  const pill = (ok, soft, txt) => `<span class="pill" style="color:${ok ? 'var(--ok)' : soft ? 'var(--warn)' : 'var(--bad)'}">${txt}</span>`;
  let h = `<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;justify-content:space-between"><b style="font:700 15px var(--f-display)">${esc(I.name || ISP_PRESETS[I.preset]?.name || 'Indoor sports hall')}</b>${R.out.length ? pill(all, false, all ? 'every court passes' : `${R.out.filter((o) => !o.pass).length} of ${R.out.length} courts to fix`) : ''}</div>
    <div class="legendRow" style="display:flex;gap:6px;align-items:center;margin:6px 0;font:11px var(--f-mono);color:var(--muted)"><span>0 lx</span><i style="flex:1;height:9px;border-radius:3px;background:linear-gradient(90deg,rgb(27,42,107) 0%,rgb(47,111,214) 31%,rgb(43,179,163) 50%,rgb(176,208,53) 62.5%,rgb(242,193,78) 81%,rgb(228,87,46) 100%)"></i><span>${Math.round(1.6 * P.Etg)} lx · lime = ${P.Etg} lx</span></div>
    <p class="note" style="margin:0 0 6px">${R.Q.length} luminaires · ${r1(R.kw, 1)} kW · ${r1((1000 * R.kw) / (I.h.L * I.h.W), 1)} W/m² · MF ${I.mf}${I.refl !== false ? ` · reflected light included (floor ${I.rho.f}, walls ${I.rho.w}, roof ${I.rho.c})` : ' · direct light only'}. White dots are luminaires (a line shows the aiming), dashed lines the trusses or frames, hatching the no-luminaire zones, grey boxes obstructions, yellow dashes roof lights${I.tv.on ? ', pink the cameras' : ''}.</p>`;
  h += `<div class="tablewrap"><table class="sch"><thead><tr><th>Court</th><th>Eav</th><th>Emin / Eav</th><th>Free height</th><th>Result</th></tr></thead><tbody>${R.out.map((o, i) => { const bad = o.ch.filter((x) => !x.ok); return `<tr data-ispc="${i}" style="cursor:pointer${ISPSEL === i ? ';background:rgba(42,111,219,.1)' : ''}"><td><b>${i + 1} · ${esc(o.S.name)}</b><br><small>${esc(o.t.src)} · grid ${o.G.nx} × ${o.G.ny}${o.c.tv && I.tv.on ? ' · TV' : ''}</small></td><td class="m" style="color:${o.av >= o.t.E ? 'var(--ok)' : 'var(--bad)'}">${Math.round(o.av)} lx<br><small>≥ ${o.t.E}</small></td><td class="m" style="color:${o.U2 >= o.t.U ? 'var(--ok)' : 'var(--bad)'}">${r1(o.U2, 2)}<br><small>≥ ${o.t.U}</small></td><td class="m" style="color:${o.fh >= o.need ? 'var(--ok)' : 'var(--bad)'}">${r1(o.fh, 1)} m<br><small>≥ ${o.need}</small></td><td>${bad.length ? `<span style="color:${bad.every((x) => x.soft) ? 'var(--warn)' : 'var(--bad)'}">${bad.length} to check</span>` : '<span style="color:var(--ok)">✓ all pass</span>'}</td></tr>${bad.length ? `<tr data-ispc="${i}" style="cursor:pointer"><td colspan="5" style="padding-top:0">${bad.map((x) => `<div style="color:${x.soft ? 'var(--warn)' : 'var(--bad)'}">${x.soft ? '!' : '✗'} ${esc(x.t)}: ${esc(x.v)}</div>`).join('')}</td></tr>` : ''}`; }).join('') || '<tr><td colspan="5" class="note">Add a court.</td></tr>'}</tbody></table></div>`;
  const sel = R.out[ISPSEL ?? -1]; if (sel) h += `<details open style="margin-top:6px"><summary><b>Court ${ISPSEL + 1} – every check</b></summary><table class="sch">${sel.ch.map((x) => `<tr><td style="color:${x.ok ? 'var(--ok)' : x.soft ? 'var(--warn)' : 'var(--bad)'}">${x.ok ? '✓' : x.soft ? '!' : '✗'}</td><td><b>${esc(x.t)}</b><br>${esc(x.v)}</td></tr>`).join('')}</table></details>`;
  if (R.Q.length && R.out.length) { const H = ispHalf(I), RH = ispCalc(I, { Q: H, fast: true }); h += `<details style="margin-top:6px"><summary><b>Switching levels</b> <span class="note">competition all on · training on the A circuits</span></summary><table class="sch"><thead><tr><th>Court</th><th>All on (${R.Q.length})</th><th>A circuits only (${H.length})</th><th>Training target (class III)</th></tr></thead><tbody>${RH.out.map((o, i) => { const T3 = ispSp(I, o.c.sp).E[2]; return `<tr><td>${i + 1} · ${esc(o.S.name)}</td><td class="m">${Math.round(R.out[i]?.av ?? 0)} lx · ${r1(R.out[i]?.U2 ?? 0, 2)}</td><td class="m" style="color:${o.av >= T3[0] && o.U2 >= T3[1] ? 'var(--ok)' : 'var(--bad)'}">${Math.round(o.av)} lx · ${r1(o.U2, 2)}</td><td class="m">${T3[0]} lx · ${T3[1]}</td></tr>`; }).join('')}</tbody></table><p class="note" style="margin:4px 0 0">Every other luminaire on each line is on circuit A, the rest on B (estimate with average reflected light). Send to electrical wires them that way.</p></details>`; }
  if (R.day) h += `<p class="note" style="margin:6px 0 0"><b>Daylight:</b> roof lights ${r1(R.day.Ag, 0)} m² (${r1(R.day.pct, 1)} % of the floor) – average daylight factor about ${r1(R.day.DF, 1)} %, about ${Math.round(R.day.E)} lx on the floor under a ${I.Eext} lx overcast sky. The artificial lighting meets the targets on its own (evening play); daylight lets it dim by day.</p>`;
  h += `<h4 style="margin:10px 0 4px">Section</h4><div class="tablewrap"><svg viewBox="${sec.vb}" width="${sec.w}" height="${sec.h}" style="max-width:100%;height:auto">${sec.s}</svg></div>`;
  $('#ispRes').innerHTML = h; $('#ispInsp').innerHTML = ispInspHtml(I, R); ispBind(I);
  $('#ispRes').querySelectorAll('[data-ispc]').forEach((tr) => tr.addEventListener('click', () => { ISPSEL = ISPSEL === +tr.dataset.ispc ? null : +tr.dataset.ispc; renderIsp(); }));
}
let ISPSEL = null;
function ispInspHtml(I, R) {
  const num = (lab, id, v, a = 'step="any"') => field(lab, id, v, 'number', a), g2 = (a, b) => `<div class="grid2">${a}${b}</div>`, g3 = (a, b, c) => `<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px">${a}${b}${c}</div>`, spOpts = Object.entries(ISP_SP).map(([k, s]) => [k, s.name]), used = [...new Set(I.courts.map((c) => c.sp))];
  let h = `<div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn" id="isp_auto" style="background:#c8102e;color:#fff;border-color:#c8102e;flex:1 1 100%;font-size:14px;padding:9px">${ISPBUSY ? 'Designing…' : 'Find the best layout'}</button><button class="btn" id="isp_send" style="background:var(--ink);color:var(--bg)">⇢ Send to electrical</button><button class="btn" id="isp_rdf" title="A new Relux project with every luminaire, its position, aiming and photometry, the main court as the calculation area and the cameras">Export .rdf</button><button class="btn" id="isp_dxf" title="The hall drawing – walls, trusses, courts, luminaires, obstructions, roof lights and cameras – as a DXF plan in metres, at the same place as the .rdf">Export .dxf</button><button class="btn" id="isp_sheet">Sheets</button></div>${ISPMSG ? `<p class="note" style="margin:0">${esc(ISPMSG)}</p>` : ''}`;
  h += `<details open><summary><b>Example halls</b></summary><div style="display:flex;gap:6px;align-items:end">${selectF('Start from', 'isp_pre', I.preset ?? -1, [[-1, '– your own hall –'], ...ISP_PRESETS.map((p, i) => [i, p.name])])}<button class="btn" id="isp_load">Load</button></div>${field('Name of the hall', 'isp_name', I.name || '', 'text')}</details>`;
  h += `<details open><summary><b>Hall &amp; structure</b></summary>${g2(num('Length m', 'isp_L', I.h.L, 'min="8" step="0.5"'), num('Width m', 'isp_W', I.h.W, 'min="6" step="0.5"'))}${g2(selectF('Structure', 'isp_st', I.h.st, Object.entries(ISP_ST)), selectF('Roof', 'isp_roof', I.h.st === 'slab' ? 'flat' : I.h.roof, ISP_ROOFS))}${g2(num(I.h.st === 'slab' ? 'Slab soffit height m' : I.h.st === 'truss' ? 'Bottom chord height m' : 'Eaves height m', 'isp_He', I.h.He, 'min="2.5" step="0.1"'), num('Ridge / crown height m', 'isp_Hr', I.h.Hr, `min="2.5" step="0.1"${I.h.st === 'slab' || I.h.roof === 'flat' ? ' disabled' : ''}`))}${g2(num('Truss / frame spacing m', 'isp_sp', I.h.sp, `min="2" step="0.5"${I.h.st === 'slab' ? ' disabled' : ''}`), num('Luminaires hang below the steel m', 'isp_drop', I.h.drop, 'min="0" step="0.1"'))}</details>`;
  h += `<details open><summary><b>Courts</b> <span class="note">${I.courts.length}</span></summary>${I.courts.map((c, i) => `<div style="display:grid;grid-template-columns:minmax(0,1.7fr) 1fr 1fr auto auto;gap:6px;align-items:end;margin-bottom:4px">${selectF(`Court ${i + 1}`, `isp_c${i}_sp`, c.sp, spOpts)}${num('x m', `isp_c${i}_x`, c.x, 'step="0.5"')}${num('y m', `isp_c${i}_y`, c.y, 'step="0.5"')}<label class="chk" title="Turn the court 90°"><input type="checkbox" id="isp_c${i}_rot"${c.rot ? ' checked' : ''}>90°</label><button class="btn" data-ispdel="${i}" aria-label="Remove court ${i + 1}">×</button></div><div style="display:flex;gap:10px;flex-wrap:wrap;margin:-2px 0 6px"><label class="chk"><select id="isp_c${i}_cls" style="font-size:11px"><option value=""${c.cls == null ? ' selected' : ''}>Class as the project</option>${['I', 'II', 'III'].map((n, k) => `<option value="${k}"${c.cls === k ? ' selected' : ''}>Class ${n} for this court</option>`).join('')}</select></label>${I.tv.on ? `<label class="chk"><input type="checkbox" id="isp_c${i}_tv"${c.tv ? ' checked' : ''}> televised</label>` : ''}</div>`).join('')}<div style="display:flex;gap:6px;align-items:end">${selectF('Sport', 'isp_fsp', I.fsp ?? 'badminton', spOpts)}<button class="btn" id="isp_fill">Fill the hall</button><button class="btn" id="isp_add">Add one</button></div><p class="note" style="margin:4px 0 0">x, y: the court centre from the left and top walls. Overlaid courts (a multi-use hall) are each checked. Tap a court in the results to see every check.</p>${used.includes('custom') ? `<h3>Custom sport</h3>${g3(field('Name', 'isp_cu_name', I.cu?.name ?? 'Custom sport', 'text'), num('Court L m', 'isp_cu_L', I.cu?.L ?? 20), num('Court W m', 'isp_cu_W', I.cu?.W ?? 10))}${g3(num('Run-off m', 'isp_cu_R', I.cu?.R ?? 2), num('Eav lx', 'isp_cu_E', I.cu?.E ?? 500), num('Emin / Eav', 'isp_cu_U', I.cu?.U ?? 0.6))}${num('Free height m', 'isp_cu_H', I.cu?.H ?? 7)}` : ''}</details>`;
  h += `<details open><summary><b>Standard &amp; targets</b></summary>${g2(selectF('EN 12193 class', 'isp_cls', I.cls, [[0, 'I – top-level competition'], [1, 'II – mid-level, clubs, schools'], [2, 'III – training, recreation']]), num('Maintenance factor', 'isp_mf', I.mf, 'min="0.4" max="1" step="0.05"'))}<label class="chk"><input type="checkbox" id="isp_nl"${I.nl !== false ? ' checked' : ''}> Keep luminaires off the playing area where the sport needs it (badminton, pools)</label><label class="chk"><input type="checkbox" id="isp_refl"${I.refl !== false ? ' checked' : ''}> Include light reflected by the floor, walls and roof</label>${g3(num('Floor ρ', 'isp_rf', I.rho.f, 'min="0" max="0.9" step="0.05"'), num('Walls ρ', 'isp_rw', I.rho.w, 'min="0" max="0.9" step="0.05"'), num('Roof ρ', 'isp_rc', I.rho.c, 'min="0" max="0.9" step="0.05"'))}
    <div class="tablewrap"><table class="sch"><thead><tr><th>Sport · class</th><th>Eav lx</th><th>Emin / Eav</th><th>Free m</th></tr></thead><tbody>${[...new Set(I.courts.map((c) => `${c.sp}:${ispCls(I, c)}`))].map((key) => { const [sp, k] = key.split(':'), c = { sp, cls: +k }, t = ispTarget(I, c); return `<tr><td>${esc(ispSp(I, sp).name)} · ${['I', 'II', 'III'][+k]}<br><small>${esc(t.src)}</small></td><td><input type="number" style="width:70px" data-isptg="${key}:E" value="${t.E}"></td><td><input type="number" style="width:60px" step="0.05" data-isptg="${key}:U" value="${t.U}"></td><td class="m">${ispSp(I, sp).free[+k]}</td></tr>`; }).join('')}</tbody></table></div><p class="note" style="margin:4px 0 0">Values entered from EN 12193:2018 Annex A – check them against your copy; change any figure to the client's or the federation's and it is marked as the project specification. Free heights are typical federation figures – the event's rules decide. <button class="btn" id="isp_tgreset" style="font-size:11px;padding:2px 8px">Back to the standard</button></p></details>`;
  const lumRows = Object.entries(I.lums).map(([id, p]) => `<tr><td><label class="chk"><input type="checkbox" data-ispuse="${id}"${p.use !== false ? ' checked' : ''}></label></td><td>${id === I.lum ? '<b>' : ''}${esc(p.name)}${id === I.lum ? '</b> ★' : ''}<br><small>${Math.round(p.lm || 0)} lm · ${p.W} W · ${Math.round((p.lm || 0) / Math.max(1, p.W))} lm/W</small></td><td><input type="number" style="width:46px" data-isplx="${id}:Ra" value="${p.Ra ?? 80}"></td><td><input type="number" style="width:58px" data-isplx="${id}:cct" value="${p.cct ?? ''}"></td><td><input type="number" style="width:46px" step="0.1" placeholder="?" data-isplx="${id}:flk" value="${p.flk ?? ''}"></td><td>${p.demo ? '' : `<button class="btn" data-ispldel="${id}" style="padding:2px 7px">×</button>`}</td></tr>`).join('');
  h += `<details open><summary><b>Luminaires</b></summary><div class="tablewrap"><table class="sch"><thead><tr><th>Try</th><th>Luminaire</th><th>Ra</th><th>K</th><th>Flicker %</th><th></th></tr></thead><tbody>${lumRows}</tbody></table></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:4px"><label class="btn" style="cursor:pointer">Add IES / LDT files<input type="file" id="isp_file" accept=".ies,.ldt,.IES,.LDT" multiple hidden></label>${Object.values(LC().lums ?? {}).some((p) => !p.demo) ? '<button class="btn" id="isp_fromlc">Copy from Lighting calc</button>' : ''}</div><p class="note" style="margin:4px 0 0">The search tries every ticked luminaire. Ra, colour temperature and flicker come from the datasheet (an IES file does not carry them) – flicker matters for TV slow motion. ★ = in use now.</p></details>`;
  h += `<details open><summary><b>Layout</b> <span class="note">${R.Q.length} luminaires</span></summary>${g2(selectF('Luminaire in use', 'isp_lum', I.lum, Object.entries(I.lums).map(([id, p]) => [id, p.name])), selectF('Mounting', 'isp_mode', I.lay.mode, [...(ispTrusses(I).length ? [['truss', 'On the trusses / frames (no extra steel)']] : []), ['rows', 'Rows along the hall (unistrut or wire)'], ['wall', 'Aimed from the side walls']]))}${I.lay.mode === 'truss' ? g2(num('Per truss / frame', 'isp_n', I.lay.n, 'min="1" max="40" step="1"'), selectF('Turn the luminaires', 'isp_spin', I.lay.spin || 0, [[0, 'C0 along the hall'], [90, 'C0 across the hall']])) : I.lay.mode === 'rows' ? g3(num('Rows', 'isp_r', I.lay.r, 'min="1" max="12" step="1"'), num('Per row', 'isp_nr', I.lay.nr, 'min="1" max="60" step="1"'), selectF('Turn', 'isp_spin', I.lay.spin || 0, [[0, 'C0 along'], [90, 'C0 across']])) : g3(num('Per wall', 'isp_wn', I.lay.wn, 'min="1" max="60" step="1"'), num('Height m', 'isp_wh', I.lay.wh, 'min="2.5" step="0.5"'), num('Aim across (0–1)', 'isp_aim', I.lay.aim, 'min="0.1" max="0.9" step="0.05"'))}${I.lay.mode !== 'wall' ? g2(num('Tilt from straight down °', 'isp_tilt', I.lay.tilt || 0, 'min="0" max="60" step="5"'), selectF('Tilted', 'isp_tdir', I.lay.tdir ?? 'cam', [['cam', 'Away from the main camera'], ['cross', 'Crossed (alternate)']])) : ''}</details>`;
  const tvl = I.tv;
  h += `<details${tvl.on ? ' open' : ''}><summary><b>TV &amp; cameras</b> <span class="note">${tvl.on ? 'on' : 'off'}</span></summary><label class="chk"><input type="checkbox" id="isp_tv"${tvl.on ? ' checked' : ''}> The event is televised – check vertical light towards the cameras, Ra and flicker on the courts ticked “televised”</label>${tvl.on ? `${g2(selectF('Level', 'isp_tvl', tvl.lvl, [...Object.entries(ISP_TV).map(([k, v]) => [k, v[0]]), ['own', 'The broadcaster’s figures']]), num('Ev to the cameras lx', 'isp_tvE', tvl.Ev, 'step="50"'))}${g3(num('U1 Emin/Emax', 'isp_tvU1', tvl.U1, 'step="0.05"'), num('U2 Emin/Eav', 'isp_tvU2', tvl.U2, 'step="0.05"'), num('Ra ≥', 'isp_tvRa', tvl.Ra, 'step="1"'))}${g2(num('Flicker ≤ %', 'isp_tvF', tvl.flk, 'step="0.1"'), num('Camera plane height m', 'isp_tvh', tvl.hc, 'step="0.1"'))}<div class="tablewrap"><table class="sch"><thead><tr><th>Camera</th><th>x</th><th>y</th><th>z</th><th></th></tr></thead><tbody>${ispCams(I).map((c, i) => `<tr><td><input type="text" data-ispcam="${i}:n" value="${esc(c.n)}" style="width:100%"></td>${['x', 'y', 'z'].map((k) => `<td><input type="number" style="width:52px" step="0.5" data-ispcam="${i}:${k}" value="${r1(c[k], 1)}"></td>`).join('')}<td><button class="btn" data-ispcamdel="${i}" style="padding:2px 7px">×</button></td></tr>`).join('')}</tbody></table></div><button class="btn" id="isp_camadd">Add a camera</button><p class="note" style="margin:4px 0 0">Ev on a vertical plane at ${tvl.hc} m facing each camera, over every point of the televised courts. The figures are typical of federation and broadcaster specifications – use the event's own.</p>` : ''}</details>`;
