  return h;
}
function ispBind(I) {
  const re = (auto = false) => { ispInv(); if (auto) ispApply(I, ispAuto(I)); renderIsp(); }, own = () => { I.preset = -1; };
  const num = (id, set, auto = false) => $('#' + id)?.addEventListener('change', (e) => { const v = parseFloat(e.target.value); if (!Number.isFinite(v)) return; set(v); own(); re(auto); });
  const sel = (id, set) => $('#' + id)?.addEventListener('change', (e) => { set(e.target.value); re(); });
  $('#isp_auto')?.addEventListener('click', () => { ISPBUSY = true; renderIsp(); setTimeout(() => { ispApply(I, ispAuto(I)); ISPBUSY = false; renderIsp(); }, 30); });
  $('#isp_load')?.addEventListener('click', () => { const i = +$('#isp_pre').value; if (i < 0) return; ISPBUSY = true; renderIsp(); setTimeout(() => { ispPreset(I, i); ISPSEL = null; ISPBUSY = false; renderIsp(); }, 30); });
  $('#isp_name')?.addEventListener('change', (e) => { I.name = e.target.value; renderIsp(); });
  num('isp_L', (v) => (I.h.L = Math.max(8, v))); num('isp_W', (v) => (I.h.W = Math.max(6, v))); num('isp_He', (v) => { I.h.He = Math.max(2.5, v); if (I.h.Hr < I.h.He) I.h.Hr = I.h.He; }); num('isp_Hr', (v) => (I.h.Hr = Math.max(I.h.He, v))); num('isp_sp', (v) => (I.h.sp = Math.max(2, v))); num('isp_drop', (v) => (I.h.drop = Math.max(0, v)));
