// ---------- send to electrical: a distribution board for the hall, the luminaires on lighting circuits (A / B alternate per line for the training level)
function ispSend(I) {
  const Q = ispPos(I); if (!Q.length) return 'There are no luminaires to send.';
  const mdb = tree.kids?.[0]; if (!mdb || mdb.t !== 'board') return 'The design has no main board to feed the hall from.';
  const nm = I.name || ISP_PRESETS[I.preset]?.name?.split(' – ')[0] || 'Sports hall', pmW = (q) => +q.pm.W || 100, maxW = 2200, cs = [];
  const by = new Map(); Q.forEach((q) => { if (!by.has(q.line)) by.set(q.line, []); by.get(q.line).push(q); });
  [...by.entries()].sort((a, b) => a[0] - b[0]).forEach(([ln, qs]) => ['A', 'B'].forEach((ab, k) => { const part = qs.filter((_, i) => i % 2 === k); for (let i = 0; i < part.length;) { let w = 0; const g = []; while (i < part.length && (w + pmW(part[i]) <= maxW || !g.length)) { w += pmW(part[i]); g.push(part[i]); i++; } cs.push({ ln, ab, g, w }); } }));
  const hasK = KNX.on, ctrl = hasK ? 'knx' : 'bms', lineName = I.lay.mode === 'truss' ? 'truss' : I.lay.mode === 'wall' ? 'wall' : 'row', dbX = 0, dbY = I.h.W / 2;
  const kids = cs.map((c, i) => { const far = Math.max(...c.g.map((q) => Math.abs(q.x - dbX) + Math.abs(q.y - dbY) + q.z)), wEach = Math.round(c.w / c.g.length); return L('light', `HL${i + 1} ${lineName} ${c.ln + 1} – ${c.ab} (${c.g.length} × ${wEach} W)`, c.w / 1000, Math.ceil(far + 5), { lamps: c.g.length, w: wEach, ctrl, isp: true }); });
  kids.push(L('light', 'Escape & standby lighting (EN 1838) – by others', 0.3, 40, { life: true, ess: true, method: 'C', grp: 1 }), L('spare', 'Spare', 0, 0));
  const old = mdb.kids.findIndex((k) => k.isp), b = B('DB', `DB-${nm.replace(/\s+/g, ' ').slice(0, 24)}`, old >= 0 ? mdb.kids[old].len : 30, kids, { isp: true });
  if (old >= 0) mdb.kids[old] = b; else mdb.kids.push(b);
  return `Sent: ${b.name} on the main board with ${cs.length} lighting circuits (${Q.length} luminaires, ${r1(Q.reduce((s, q) => s + pmW(q), 0) / 1000, 1)} kW), A and B alternate on each ${lineName} for the training level, ${hasK ? 'KNX control' : 'contactors from the BMS'}${old >= 0 ? ' – the board sent before was replaced' : ''}. Check the cable lengths in Single line diagram.`;
}
