  ispTrusses(I).forEach((x) => o.push('0', 'LINE', '8', 'DIMO-STRUCTURE', '10', f(x + ox), '20', f(oy), '30', f(I.h.He), '11', f(x + ox), '21', f(I.h.W + oy), '31', f(I.h.He)));
